INSERT INTO [interview_topics] ([id], [name], [description], [display_order], [is_active], [created_at], [updated_at], [created_by], [updated_by]) VALUES
(1, N'Java & Spring Boot Fresher', N'Phỏng vấn kiến thức Java Core, OOP, Spring Boot, JPA/Hibernate và REST API.', 1, 1, '2026-11-10 06:25:14.431', '2026-11-10 06:25:14.431', NULL, NULL),
(2, N'.NET & ASP.NET Core Fresher', N'Phỏng vấn C#, .NET 8, Dependency Injection, Entity Framework Core và LINQ.', 2, 1, '2026-11-10 06:25:14.431', '2026-11-10 06:25:14.431', NULL, NULL),
(3, N'Frontend React & TypeScript Fresher', N'Phỏng vấn JavaScript ES6+, TypeScript, React Hooks, State Management và hiệu năng UI.', 3, 1, '2026-11-10 06:25:14.431', '2026-11-10 06:25:14.431', NULL, NULL),
(4, N'Fullstack JavaScript / Node.js Fresher', N'Phỏng vấn Node.js, Express, Event Loop, Async/Await và kiến trúc Fullstack.', 4, 1, '2026-11-10 06:25:14.431', '2026-11-10 06:25:14.431', NULL, NULL),
(5, N'Database & SQL Backend Developer', N'Phỏng vấn SQL Server, Index, Transaction, Query Optimization và thiết kế CSDL.', 5, 1, '2026-11-10 06:25:14.431', '2026-11-10 06:25:14.431', NULL, NULL);
INSERT INTO [interview_questions] ([id], [topic_id], [question_text], [sample_answer], [difficulty], [display_order], [is_active], [created_at], [updated_at], [created_by], [updated_by], [keywords], [question_type], [options_json], [correct_option_id]) VALUES
(1, 1, N'Phân biệt Abstract Class và Interface trong Java? Khi nào nên dùng loại nào?', N'Abstract class có thể chứa field trạng thái, constructor và method có thân hàm, hỗ trợ kế thừa đơn (IS-A). Interface định nghĩa hợp đồng hành vi (CAN-DO), hỗ trợ đa kế thừa (từ Java 8 có default/static method). Dùng Abstract Class khi chia sẻ logic chung giữa các lớp liên quan chặt chẽ; dùng Interface để tách biệt hành vi và hỗ trợ đa hình linh hoạt.', N'EASY', 1, 1, '2026-11-10 06:25:14.460', '2026-11-18 12:42:57.420', NULL, NULL, N'abstract class, interface, kế thừa đơn, đa kế thừa, constructor, default method', N'WRITTEN', NULL, NULL),
(2, 1, N'Dependency Injection (DI) và IoC Container trong Spring Boot hoạt động như thế nào?', N'IoC (Inversion of Control) đảo ngược quyền điều khiển việc khởi tạo object giao cho Spring Container quản lý vòng đời Bean. DI là kỹ thuật truyền phụ thuộc (qua Constructor, Setter, Field) giúp giảm sự phụ thuộc cứng (loose coupling) và dễ viết Unit Test.', N'MEDIUM', 2, 1, '2026-11-10 06:25:14.460', '2026-11-16 03:17:52.853', NULL, NULL, N'IoC, Dependency Injection, Bean, Container, loose coupling, unit test', N'WRITTEN', NULL, NULL),
(3, 1, N'Vấn đề N+1 Query trong Hibernate/JPA là gì và cách khắc phục?', N'N+1 xảy ra khi tải 1 danh sách gồm N bản ghi cha (1 query), rồi với mỗi bản ghi cha lại chạy thêm 1 query lấy dữ liệu con (N queries) do Lazy Loading. Khắc phục bằng JOIN FETCH trong JPQL, @EntityGraph, hoặc cấu hình @BatchSize.', N'HARD', 3, 1, '2026-11-10 06:25:14.460', '2026-11-18 12:42:57.420', NULL, NULL, N'N+1, Lazy Loading, JOIN FETCH, EntityGraph, BatchSize', N'WRITTEN', NULL, NULL),
(4, 2, N'So sánh vòng đời Service: Transient, Scoped và Singleton trong ASP.NET Core DI?', N'Transient: tạo mới mỗi lần được yêu cầu (inject). Scoped: tạo 1 lần duy nhất cho mỗi HTTP Request (rất phù hợp cho DbContext/Repository). Singleton: tạo 1 lần duy nhất suốt vòng đời ứng dụng.', N'EASY', 1, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'Transient, Scoped, Singleton, HTTP Request, DbContext, vòng đời', N'WRITTEN', NULL, NULL),
(5, 2, N'AsNoTracking() và IQueryable<T> khác với IEnumerable<T> trong Entity Framework Core như thế nào?', N'IQueryable thực thi lọc/phân trang ngay dưới Database (xây dựng Expression Tree dịch ra SQL), còn IEnumerable kéo dữ liệu về RAM rồi mới lọc. AsNoTracking tắt Change Tracker của EF Core giúp tăng tốc độ đọc và tiết kiệm RAM cho các API chỉ đọc.', N'MEDIUM', 2, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'IQueryable, IEnumerable, SQL, RAM, Change Tracker, AsNoTracking', N'WRITTEN', NULL, NULL),
(6, 2, N'Middleware Pipeline trong ASP.NET Core hoạt động theo cơ chế nào? Thứ tự UseAuthentication và UseAuthorization quan trọng ra sao?', N'Middleware hoạt động theo mô hình đường ống hai chiều (Request đi vào qua next(), Response đi ngược ra). UseAuthentication phải đặt trước UseAuthorization để hệ thống xác thực danh tính người dùng từ Token/Cookie trước khi kiểm tra quyền truy cập.', N'MEDIUM', 3, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'Middleware, pipeline, next, UseAuthentication, UseAuthorization, token', N'WRITTEN', NULL, NULL),
(7, 3, N'useEffect trong React chạy khi nào? Làm sao xử lý cleanup và tránh vòng lặp vô hạn?', N'useEffect chạy sau khi component render xong. Dependency array [] chạy 1 lần khi mount; [dep] chạy khi dep thay đổi. Tránh lặp vô hạn bằng cách không setState trực tiếp gây thay đổi dependency bên trong chính effect đó. Hàm return trong useEffect dùng để dọn dẹp timer/subscription khi unmount.', N'EASY', 1, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'useEffect, render, dependency array, cleanup, unmount, vòng lặp vô hạn', N'WRITTEN', NULL, NULL),
(8, 3, N'Phân biệt React.memo, useMemo và useCallback trong tối ưu hiệu năng React?', N'React.memo bọc Component để bỏ qua re-render nếu props không đổi. useMemo ghi nhớ kết quả tính toán phức tạp. useCallback ghi nhớ tham chiếu hàm truyền xuống component con để không phá vỡ React.memo.', N'MEDIUM', 2, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'React.memo, useMemo, useCallback, re-render, props, tham chiếu', N'WRITTEN', NULL, NULL),
(9, 3, N'Tại sao dùng TypeScript giúp ứng dụng Frontend dễ bảo trì hơn JavaScript thuần?', N'TypeScript kiểm tra kiểu tĩnh lúc biên dịch (compile-time), phát hiện sớm lỗi sai kiểu dữ liệu/null/undefined, cung cấp IntelliSense gợi ý code chuẩn xác và giúp refactor code an toàn trên dự án lớn.', N'EASY', 3, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'TypeScript, static typing, compile-time, IntelliSense, refactor', N'WRITTEN', NULL, NULL),
(10, 4, N'Event Loop trong Node.js hoạt động như thế nào để xử lý bất đồng bộ đơn luồng?', N'Node.js chạy trên Call Stack đơn luồng, các tác vụ I/O nặng được đẩy sang libuv thread pool hoặc OS kernel. Khi hoàn thành, callback được đưa vào các hàng đợi (Microtasks như Promise, Macrotasks như setTimeout/I/O) và Event Loop sẽ đưa về Call Stack thực thi khi Stack rỗng.', N'MEDIUM', 1, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'Event Loop, single-threaded, libuv, Call Stack, Microtask, Macrotask', N'WRITTEN', NULL, NULL),
(11, 4, N'Phân biệt JWT (Stateless) và Session (Stateful) trong xác thực API?', N'Session lưu trạng thái trên bộ nhớ server (RAM/Redis) và trả về sessionId qua cookie. JWT tự chứa thông tin (claims) có chữ ký số gửi kèm Header Authorization; server không cần lưu trạng thái nên dễ scale ngang, nhưng khó thu hồi token trước hạn nếu không có blacklist/refresh token.', N'MEDIUM', 2, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'JWT, Session, stateless, stateful, cookie, Authorization, scale', N'WRITTEN', NULL, NULL),
(12, 5, N'Clustered Index và Non-Clustered Index trong SQL Server khác nhau như thế nào?', N'Clustered Index sắp xếp vật lý chính dữ liệu của bảng (mỗi bảng chỉ có tối đa 1 Clustered Index, thường là Primary Key). Non-Clustered Index tạo cấu trúc B-Tree riêng chứa khóa và con trỏ trỏ về dữ liệu gốc (mỗi bảng có thể có nhiều cái); có thể dùng INCLUDE để tạo Covering Index tránh Key Lookup.', N'MEDIUM', 1, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'Clustered, Non-Clustered, B-Tree, vật lý, Key Lookup, INCLUDE', N'WRITTEN', NULL, NULL),
(13, 5, N'4 tính chất ACID của Transaction trong cơ sở dữ liệu là gì?', N'Atomicity (Nguyên tử: thành công tất cả hoặc rollback tất cả), Consistency (Nhất quán: dữ liệu luôn hợp lệ theo ràng buộc), Isolation (Cô lập: các transaction đồng thời không làm sai lệch nhau), Durability (Bền vững: đã commit thì không mất kể cả mất điện).', N'EASY', 2, 1, '2026-11-10 06:25:14.460', '2026-11-10 06:25:14.460', NULL, NULL, N'ACID, Atomicity, Consistency, Isolation, Durability, rollback, commit', N'WRITTEN', NULL, NULL),
(14, 1, N'HashMap trong Java hoạt động bên trong như thế nào? Xử lý đụng độ (Collision) ra sao?', N'HashMap lưu trữ cặp Key-Value dựa trên mảng các Bucket. Nó gọi hashCode() để tính vị trí index của bucket và dùng equals() để kiểm tra trùng key. Khi nhiều key có cùng bucket index (Hash Collision), Java 8 dùng LinkedList (và tự động chuyển sang Red-Black Tree nếu số phần tử trong 1 bucket vượt quá ngưỡng TREEIFY_THRESHOLD = 8) để đạt tốc độ O(log n).', N'MEDIUM', 4, 1, '2026-11-10 06:56:02.918', '2026-11-18 13:07:13.439', NULL, NULL, N'hashCode, equals, bucket, collision, LinkedList, Red-Black Tree', N'WRITTEN', NULL, NULL),
(15, 2, N'Cơ chế async/await và Task trong C# giải quyết vấn đề gì? Khác biệt giữa Task.Run và I/O async?', N'async/await cho phép lập trình bất đồng bộ không khóa luồng (non-blocking). Khi chờ I/O (như truy vấn DB, gọi API), thread hiện tại được trả về ThreadPool để phục vụ request khác giúp tăng khả năng chịu tải server. Task.Run đẩy công việc CPU-bound sang thread khác trong ThreadPool, không nên lạm dụng Task.Run bọc cho tác vụ I/O async thuần túy.', N'MEDIUM', 4, 1, '2026-11-10 06:56:02.921', '2026-11-10 06:56:02.921', NULL, NULL, N'async, await, Task, non-blocking, ThreadPool, I/O, CPU-bound', N'WRITTEN', NULL, NULL),
(16, 3, N'Virtual DOM là gì và thuật toán Reconciliation (Diffing) của React hoạt động ra sao?', N'Virtual DOM là bản sao nhẹ của Real DOM dưới dạng cây đối tượng JavaScript trên RAM. Khi state thay đổi, React tạo cây Virtual DOM mới, chạy thuật toán Diffing (so sánh 2 cây với độ phức tạp O(n) nhờ key prop và kiểu element) để tìm ra đúng những node bị thay đổi rồi mới cập nhật hàng loạt vào Real DOM thật, giúp tối ưu hiệu năng vẽ lại giao diện.', N'MEDIUM', 4, 1, '2026-11-10 06:56:02.922', '2026-11-10 06:56:02.922', NULL, NULL, N'Virtual DOM, Real DOM, Diffing, Reconciliation, key, state', N'WRITTEN', NULL, NULL),
(17, 4, N'So sánh Promise.all, Promise.allSettled và Promise.race trong JavaScript?', N'Promise.all chạy song song nhiều Promise và trả về mảng kết quả khi TẤT CẢ thành công, nhưng sẽ reject ngay lập tức nếu 1 Promise bị lỗi (fail-fast). Promise.allSettled chờ TẤT CẢ kết thúc dù thành công hay thất bại và trả về trạng thái fulfilled/rejected của từng cái. Promise.race trả về kết quả của Promise hoàn thành (resolve hoặc reject) đầu tiên.', N'EASY', 3, 1, '2026-11-10 06:56:02.922', '2026-11-10 06:56:02.922', NULL, NULL, N'Promise.all, Promise.allSettled, Promise.race, song song, reject, fulfilled', N'WRITTEN', NULL, NULL),
(18, 4, N'Làm thế nào để xử lý lỗi tập trung (Global Error Handling) trong ExpressJS?', N'Trong ExpressJS, ta định nghĩa Error-handling Middleware ở cuối chuỗi route với đủ 4 tham số (err, req, res, next). Khi bất kỳ route hoặc async controller nào gọi next(err) (hoặc dùng express-async-errors), Express tự động nhảy thẳng tới middleware này để log lỗi và trả về JSON HTTP status code thống nhất cho Client.', N'MEDIUM', 4, 1, '2026-11-10 06:56:02.922', '2026-11-10 06:56:02.922', NULL, NULL, N'middleware, 4 tham số, err req res next, next(err), HTTP status', N'WRITTEN', NULL, NULL),
(19, 5, N'Phân biệt mệnh đề WHERE và HAVING trong SQL? Thứ tự thực thi của chúng ra sao?', N'WHERE dùng để lọc từng dòng dữ liệu THÔ trước khi gom nhóm (GROUP BY), không dùng được với các hàm tổng hợp như COUNT/SUM. HAVING dùng để lọc trên kết quả các NHÓM đã được gom bởi GROUP BY và thường kết hợp với hàm tổng hợp (VD: HAVING COUNT(*) > 5). Theo thứ tự thực thi SQL: FROM -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY.', N'EASY', 3, 1, '2026-11-10 06:56:02.923', '2026-11-10 06:56:02.923', NULL, NULL, N'WHERE, HAVING, GROUP BY, hàm tổng hợp, COUNT, SUM, thứ tự thực thi', N'WRITTEN', NULL, NULL),
(20, 5, N'Covering Index (INCLUDE) dùng để làm gì và khắc phục lỗi hiệu năng nào trong SQL Server?', N'Covering Index sử dụng từ khóa INCLUDE để nhúng thêm các cột cần SELECT (nhưng không dùng để tìm kiếm/lọc) vào thẳng trang lá (Leaf Page) của Non-Clustered Index. Nhờ đó, SQL Server lấy được toàn bộ dữ liệu chỉ qua Index Seek mà không cần thực hiện Key Lookup quay lại bảng gốc, giúp giảm mạnh I/O và tăng tốc truy vấn.', N'HARD', 4, 1, '2026-11-10 06:56:02.923', '2026-11-10 06:56:02.923', NULL, NULL, N'Covering Index, INCLUDE, Leaf Page, Index Seek, Key Lookup, I/O', N'WRITTEN', NULL, NULL),
(21, 1, N'Scope mặc định của một Spring Bean trong Spring Framework / Spring Boot là gì?', N'Spring Bean mặc định có scope là Singleton, nghĩa là chỉ có duy nhất 1 instance được khởi tạo và chia sẻ trong toàn bộ Spring IoC Container.', N'EASY', 0, 1, '2026-11-16 02:05:57.861', '2026-11-16 07:38:07.934', NULL, NULL, N'Singleton, Spring IoC, Scope, Instance', N'MCQ', N'[{"id":"A","text":"Prototype"},{"id":"B","text":"Singleton"},{"id":"C","text":"Request"},{"id":"D","text":"Session"}]', N'B'),
(22, 1, N'Annotation nào trong Spring Boot dùng để khai báo một REST API Controller tự động serialize đối tượng trả về thành JSON?', N'@RestController là sự kết hợp của @Controller và @ResponseBody, tự động chuyển đổi return object thành JSON response.', N'EASY', 0, 1, '2026-11-16 02:05:57.916', '2026-11-19 01:40:28.043', NULL, NULL, N'@RestController, JSON, @ResponseBody, Controller', N'MCQ', N'[{"id":"A","text":"@Controller"},{"id":"B","text":"@ResponseBody"},{"id":"C","text":"@RestController"},{"id":"D","text":"@Service"}]', N'C'),
(23, 1, N'Trong Java Collection Framework, cấu trúc dữ liệu nào sau đây KHÔNG cho phép chứa các phần tử trùng lặp (duplicate elements)?', N'Set (cụ thể là HashSet, TreeSet) là tập hợp các phần tử duy nhất, không cho phép phần tử trùng lặp.', N'EASY', 0, 1, '2026-11-16 02:05:57.925', '2026-11-18 13:07:13.439', NULL, NULL, N'HashSet, Set, Unique, Duplicate', N'MCQ', N'[{"id":"A","text":"ArrayList"},{"id":"B","text":"LinkedList"},{"id":"C","text":"HashSet"},{"id":"D","text":"Vector"}]', N'C'),
(24, 1, N'Phương thức nào trong Java được dùng để so sánh giá trị nội dung giữa hai đối tượng chuỗi String thay vì so sánh địa chỉ vùng nhớ?', N'equals() so sánh giá trị nội dung của String, trong khi toán tử == so sánh địa chỉ tham chiếu vùng nhớ trong heap.', N'MEDIUM', 0, 1, '2026-11-16 02:05:57.934', '2026-11-16 02:59:11.594', NULL, NULL, N'equals, ==, Reference, Heap, String', N'MCQ', N'[{"id":"A","text":"toán tử =="},{"id":"B","text":"phương thức equals()"},{"id":"C","text":"phương thức compareTo()"},{"id":"D","text":"phương thức matches()"}]', N'B'),
(25, 1, N'Trong Spring Data JPA, annotation nào bắt buộc dùng để đánh dấu trường khóa chính (Primary Key) của một Entity?', N'@Id trong package jakarta.persistence hoặc javax.persistence dùng để định danh thuộc tính là khóa chính của bảng.', N'EASY', 0, 1, '2026-11-16 02:05:57.940', '2026-11-19 01:40:28.043', NULL, NULL, N'@Id, Primary Key, Entity, JPA', N'MCQ', N'[{"id":"A","text":"@Id"},{"id":"B","text":"@Key"},{"id":"C","text":"@PrimaryKey"},{"id":"D","text":"@Column"}]', N'A');
INSERT INTO [interview_questions] ([id], [topic_id], [question_text], [sample_answer], [difficulty], [display_order], [is_active], [created_at], [updated_at], [created_by], [updated_by], [keywords], [question_type], [options_json], [correct_option_id]) VALUES
(26, 1, N'Annotation nào sau đây trong Spring Boot được dùng để inject một dependency thông qua Constructor hoặc Field Injection?', N'@Autowired dùng để tự động tìm kiếm bean thích hợp trong ApplicationContext và inject vào nơi sử dụng.', N'MEDIUM', 0, 1, '2026-11-16 02:05:57.948', '2026-11-19 01:40:28.043', NULL, NULL, N'@Autowired, Dependency Injection, Bean', N'MCQ', N'[{"id":"A","text":"@Injectable"},{"id":"B","text":"@Autowired"},{"id":"C","text":"@Component"},{"id":"D","text":"@Service"}]', N'B'),
(27, 1, N'Phân biệt Checked Exception và Unchecked Exception (Runtime Exception) trong Java? Cho ví dụ thực tế.', N'Checked Exception kế thừa từ Exception (ngoại trừ RuntimeException), bắt buộc phải xử lý bằng try-catch hoặc throws (VD: IOException, SQLException). Unchecked Exception kế thừa từ RuntimeException, xảy ra trong quá trình chạy và không bắt buộc try-catch (VD: NullPointerException, ArithmeticException).', N'EASY', 0, 1, '2026-11-16 02:05:57.958', '2026-11-16 07:38:07.934', NULL, NULL, N'Checked Exception, Unchecked Exception, RuntimeException, try-catch, IOException, NullPointerException', N'WRITTEN', NULL, NULL),
(28, 1, N'Tại sao nên sử dụng @Transactional trong tầng Service của Spring Boot? Cơ chế rollback mặc định hoạt động thế nào khi xảy ra Exception?', N'@Transactional đảm bảo tính toàn vẹn dữ liệu theo nguyên lý ACID. Mặc định Spring sẽ tự động rollback khi gặp RuntimeException hoặc Error, nhưng không rollback khi gặp Checked Exception trừ khi cấu hình rollbackFor = Exception.class.', N'MEDIUM', 0, 1, '2026-11-16 02:05:57.963', '2026-11-18 13:07:13.439', NULL, NULL, N'@Transactional, ACID, Rollback, RuntimeException, rollbackFor, Service layer', N'WRITTEN', NULL, NULL),
(29, 1, N'Giải thích nguyên lý SOLID trong lập trình hướng đối tượng. Nêu ví dụ về Dependency Inversion Principle (DIP) trong dự án Spring Boot.', N'SOLID gồm: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion. DIP phát biểu: Module cấp cao không nên phụ thuộc module cấp thấp, cả 2 nên phụ thuộc vào abstraction. Trong Spring Boot: Controller/Service phụ thuộc vào Interface UserRepository chứ không phụ thuộc trực tiếp vào UserRepositoryImpl.', N'HARD', 0, 1, '2026-11-16 02:05:57.968', '2026-11-18 12:42:57.420', NULL, NULL, N'SOLID, Single Responsibility, Open-Closed, Liskov, Interface Segregation, Dependency Inversion, Abstraction, Interface', N'WRITTEN', NULL, NULL),
(30, 1, N'Cơ chế Garbage Collection (GC) trong Java hoạt động thế nào? Sự khác nhau giữa vùng nhớ Heap và Stack?', N'Stack lưu trữ biến cục bộ và con trỏ tham chiếu của từng thread (nhanh, tự giải phóng khi thoát hàm). Heap lưu trữ đối tượng thực tế được tạo bằng từ khóa new. Garbage Collector tự động quét Heap và thu hồi bộ nhớ của các đối tượng không còn được tham chiếu (unreachable objects) bằng các thuật toán như Mark-and-Sweep.', N'HARD', 0, 1, '2026-11-16 02:05:57.972', '2026-11-19 01:40:28.043', NULL, NULL, N'Garbage Collection, Heap, Stack, Thread, Mark-and-Sweep, Unreachable object, Reference', N'WRITTEN', NULL, NULL),
(31, 1, N'Phân biệt Comparable và Comparator trong Java? Khi nào cần dùng Comparator thay cho Comparable?', N'Comparable nằm trong package java.lang, định nghĩa thứ tự sắp xếp tự nhiên bên trong chính class đó thông qua compareTo(). Comparator nằm trong java.util, định nghĩa chiến lược sắp xếp độc lập bên ngoài thông qua compare(), cho phép tạo nhiều tiêu chí sắp xếp khác nhau mà không cần sửa đổi class gốc.', N'MEDIUM', 0, 1, '2026-11-16 02:05:57.978', '2026-11-18 13:07:13.439', NULL, NULL, N'Comparable, Comparator, compareTo, compare, java.lang, java.util, sắp xếp', N'WRITTEN', NULL, NULL),
(32, 1, N'Trình bày cấu trúc một API chuẩn RESTful. Phân biệt phương thức PUT và PATCH khi cập nhật tài nguyên.', N'RESTful API dùng các HTTP method: GET (đọc), POST (tạo), PUT (thay thế toàn bộ tài nguyên), PATCH (cập nhật một phần thuộc tính tài nguyên), DELETE (xóa). PUT mang tính idempotent, gửi toàn bộ payload mới; PATCH chỉ gửi những trường cần cập nhật.', N'EASY', 0, 1, '2026-11-16 02:05:57.981', '2026-11-18 13:07:13.439', NULL, NULL, N'RESTful API, GET, POST, PUT, PATCH, DELETE, Idempotent, Cập nhật', N'WRITTEN', NULL, NULL),
(33, 1, N'Trong ngôn ngữ Java, từ khóa ''final'' khi áp dụng cho một phương thức (method) có ý nghĩa gì?', N'Phương thức có từ khóa final ngăn chặn việc các lớp con ghi đè (override) lại phương thức đó, bảo toàn logic nghiệp vụ cốt lõi.', N'EASY', 100, 1, '2026-11-16 04:04:42.519', '2026-11-18 13:07:13.439', NULL, NULL, N'final, method, override, kế thừa', N'MCQ', N'[{"id": "A", "text": "Phương thức không thể bị ghi đè (override) bởi lớp con"}, {"id": "B", "text": "Phương thức không thể được gọi từ lớp ngoài"}, {"id": "C", "text": "Phương thức phải trả về một hằng số"}, {"id": "D", "text": "Phương thức tự động trở thành static"}]', N'A'),
(34, 1, N'Annotation nào trong Spring Boot được sử dụng để định nghĩa một Controller tự động serialize đối tượng trả về thành JSON/XML trong HTTP Response Body?', N'@RestController kết hợp giữa @Controller và @ResponseBody, tự động chuyển đổi dữ liệu trả về thành JSON/XML.', N'EASY', 101, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.528', NULL, NULL, N'@RestController, @ResponseBody, JSON, Spring Boot', N'MCQ', N'[{"id": "A", "text": "@Controller"}, {"id": "B", "text": "@RestController"}, {"id": "C", "text": "@Service"}, {"id": "D", "text": "@Component"}]', N'B'),
(35, 1, N'Phân biệt sự khác nhau giữa toán tử ''=='' và phương thức ''equals()'' trong Java khi so sánh đối tượng?', N'Toán tử ''=='' so sánh địa chỉ ô nhớ (tham chiếu) của hai đối tượng trên Heap. Phương thức ''equals()'' so sánh giá trị nội dung logic bên trong đối tượng (mặc định trong lớp Object thì equals() dùng ''=='', nhưng thường được override trong String, Integer, custom entity để so sánh nội dung).', N'EASY', 102, 1, '2026-11-16 04:04:42.519', '2026-11-16 07:38:07.934', NULL, NULL, N'equals, so sánh, tham chiếu, vùng nhớ heap, value equality, reference equality', N'WRITTEN', NULL, NULL),
(36, 1, N'Trong Spring Data JPA, annotation nào cho phép viết câu truy vấn tùy biến bằng cú pháp JPQL hoặc Native SQL?', N'Annotation @Query được đặt trên method của Repository để thực thi câu lệnh JPQL hoặc Native SQL tùy chỉnh.', N'MEDIUM', 103, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.540', NULL, NULL, N'@Query, JPQL, Native SQL, Spring Data JPA', N'MCQ', N'[{"id": "A", "text": "@Select"}, {"id": "B", "text": "@Query"}, {"id": "C", "text": "@SqlCommand"}, {"id": "D", "text": "@JPAQuery"}]', N'B'),
(37, 1, N'Bộ thu gom rác (Garbage Collection) trong JVM chia vùng nhớ Heap thành những thế hệ (Generations) nào để tối ưu hiệu năng?', N'JVM chia Heap thành Young Generation (gồm Eden, Survivor S0, S1) và Old (Tenured) Generation, áp dụng thuật toán sao chép cho đối tượng ngắn hạn và gom dọn cho đối tượng sống lâu.', N'MEDIUM', 104, 1, '2026-11-16 04:04:42.519', '2026-11-18 13:07:13.439', NULL, NULL, N'Garbage Collection, Heap, Young Generation, Old Generation, Eden, Survivor', N'MCQ', N'[{"id": "A", "text": "Stack và Heap"}, {"id": "B", "text": "Young Generation (Eden, S0, S1) và Old Generation"}, {"id": "C", "text": "Code Segment và Data Segment"}, {"id": "D", "text": "Direct Memory và Native Memory"}]', N'B'),
(38, 1, N'Trình bày cách xử lý Exception tập trung (Global Exception Handling) trong ứng dụng Spring Boot?', N'Sử dụng kết hợp @ControllerAdvice (hoặc @RestControllerAdvice) cùng với các phương thức gắn @ExceptionHandler(CustomException.class) để bắt lỗi toàn cục, chuẩn hóa cấu trúc JSON trả về lỗi (bao gồm timestamp, status code, error message) và ghi log tập trung.', N'MEDIUM', 105, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.544', NULL, NULL, N'@ControllerAdvice, @RestControllerAdvice, @ExceptionHandler, chuẩn hóa lỗi, ResponseEntity', N'WRITTEN', NULL, NULL),
(39, 1, N'Cơ chế quản lý Transaction bằng annotation @Transactional trong Spring Boot hoạt động như thế nào và khi nào mặc định bị Rollback?', N'@Transactional hoạt động dựa trên Spring AOP Proxy bọc quanh method. Khi có RuntimeException hoặc Error không được bắt, Spring tự động rollback transaction. Nếu là Checked Exception, mặc định không rollback trừ khi cấu hình rollbackFor = Exception.class.', N'MEDIUM', 106, 1, '2026-11-16 04:04:42.519', '2026-11-19 01:40:28.043', NULL, NULL, N'@Transactional, Spring AOP, Proxy, Rollback, RuntimeException, Checked Exception', N'WRITTEN', NULL, NULL),
(40, 1, N'Phân biệt List, Set và Map trong Java Collections Framework? Khi nào nên chọn ArrayList thay vì LinkedList?', N'List lưu trữ các phần tử có thứ tự và cho phép trùng lặp. Set không cho phép trùng lặp phần tử. Map lưu trữ dữ liệu theo cặp Key-Value. Nên chọn ArrayList khi thao tác đọc ngẫu nhiên (get theo index O(1)) chiếm đa số; LinkedList chỉ lợi thế khi chèn/xóa liên tục ở đầu hoặc giữa danh sách với iterator.', N'MEDIUM', 107, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.548', NULL, NULL, N'List, Set, Map, ArrayList, LinkedList, O(1), thời gian truy xuất', N'WRITTEN', NULL, NULL),
(41, 1, N'Giải thích nguyên lý lập trình bất đồng bộ bằng CompletableFuture hoặc ExecutorService trong Java?', N'ExecutorService quản lý ThreadPool giúp tái sử dụng luồng, tránh chi phí tạo luồng mới liên tục. CompletableFuture (từ Java 8) hỗ trợ lập trình bất đồng bộ không chặn (non-blocking), cho phép kết hợp chuỗi tác vụ (thenApply, thenCompose, thenCombine) và xử lý ngoại lệ mượt mà.', N'MEDIUM', 108, 1, '2026-11-16 04:04:42.519', '2026-11-16 07:38:07.934', NULL, NULL, N'CompletableFuture, ExecutorService, ThreadPool, asynchronous, non-blocking', N'WRITTEN', NULL, NULL),
(42, 1, N'Trong một Spring Service, khi method A gọi trực tiếp method B (self-invocation) cùng nằm trong class đó, method B có gắn @Transactional. Tại sao Transaction của method B không được kích hoạt?', N'Vì Spring AOP Transaction hoạt động dựa trên Proxy Pattern. Lời gọi nội bộ (this.methodB()) không đi qua đối tượng Proxy nên interceptor transaction bị bỏ qua.', N'HARD', 109, 1, '2026-11-16 04:04:42.519', '2026-11-19 01:40:28.043', NULL, NULL, N'Spring AOP, Proxy Pattern, Self-invocation, internal call', N'MCQ', N'[{"id": "A", "text": "Do method B không có quyền public"}, {"id": "B", "text": "Do lời gọi nội bộ không đi qua Spring Proxy bọc ngoài bean"}, {"id": "C", "text": "Do Spring chỉ hỗ trợ 1 transaction trên mỗi service class"}, {"id": "D", "text": "Do database driver không hỗ trợ nested transaction"}]', N'B'),
(43, 1, N'Vấn đề ''N+1 Query'' trong Spring Data JPA / Hibernate là gì và những cách khắc phục triệt để nhất?', N'N+1 Query xảy ra khi truy vấn 1 bảng cha nhưng Hibernate sinh thêm N câu truy vấn phụ để tải thực thể con liên quan. Khắc phục bằng: Sử dụng ''JOIN FETCH'' trong câu @Query JPQL, sử dụng @EntityGraph, hoặc cấu hình @BatchSize.', N'HARD', 110, 1, '2026-11-16 04:04:42.519', '2026-11-19 01:40:28.043', NULL, NULL, N'N+1 Query, Hibernate, JOIN FETCH, EntityGraph, BatchSize, eager loading', N'WRITTEN', NULL, NULL),
(44, 1, N'Trình bày kiến trúc xác thực và phân quyền bằng JWT (JSON Web Token) kết hợp Spring Security? Phân biệt Access Token và Refresh Token?', N'Client gửi thông tin login, server xác thực và trả về cặp Access Token (thời hạn ngắn, VD: 15 phút) và Refresh Token (thời hạn dài, lưu an toàn trong HTTP-only Cookie hoặc DB). Mỗi request client gửi Bearer Access Token trong Authorization Header, OncePerRequestFilter giải mã và nạp SecurityContextHolder. Khi Access Token hết hạn, dùng Refresh Token để cấp mới.', N'HARD', 111, 1, '2026-11-16 04:04:42.519', '2026-11-19 01:40:28.043', NULL, NULL, N'Spring Security, JWT, OncePerRequestFilter, Access Token, Refresh Token, SecurityContextHolder', N'WRITTEN', NULL, NULL),
(45, 1, N'Phân biệt Optimistic Locking và Pessimistic Locking trong cơ sở dữ liệu khi làm việc với JPA/Hibernate? Cho ví dụ áp dụng thực tế?', N'Optimistic Locking không khóa dòng mà dùng cột version (@Version). Khi commit kiểm tra version, nếu trùng khớp thì tăng version, nếu lệch thì ném OptimisticLockException (phù hợp hệ thống ít xung đột đọc nhiều). Pessimistic Locking khóa trực tiếp dòng trong DB (SELECT FOR UPDATE) ngăn chặn mọi giao dịch khác (phù hợp bài toán trừ tồn kho, số dư tài khoản).', N'HARD', 112, 1, '2026-11-16 04:04:42.519', '2026-11-19 01:40:28.043', NULL, NULL, N'Optimistic Locking, Pessimistic Locking, @Version, SELECT FOR UPDATE, Concurrency', N'WRITTEN', NULL, NULL),
(46, 1, N'Trình bày các chiến lược xử lý đồng thời (Concurrency) và Race Condition trong Java (Synchronized, ReentrantLock, Atomic Classes)?', N'Synchronized là khóa ở cấp độ cú pháp JVM tự động giải phóng. ReentrantLock cung cấp khả năng khóa linh hoạt hơn (tryLock có timeout, fairness policy). AtomicInteger/AtomicReference sử dụng lệnh phần cứng CAS (Compare-And-Swap) không chặn luồng (lock-free), đạt hiệu năng cao khi cập nhật biến đếm đồng thời.', N'HARD', 113, 1, '2026-11-16 04:04:42.519', '2026-11-19 01:40:28.043', NULL, NULL, N'Concurrency, Race Condition, Synchronized, ReentrantLock, Atomic, CAS, Thread-safe', N'WRITTEN', NULL, NULL),
(47, 2, N'Trong ASP.NET Core Dependency Injection, Service đăng ký với vòng đời ''Scoped'' sẽ tồn tại trong bao lâu?', N'Scoped service được khởi tạo một lần duy nhất cho mỗi HTTP Request và được giải phóng khi request đó kết thúc.', N'EASY', 114, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.560', NULL, NULL, N'Scoped, Dependency Injection, vòng đời, HTTP Request', N'MCQ', N'[{"id": "A", "text": "Tạo mới mỗi khi được inject"}, {"id": "B", "text": "Tạo một lần duy nhất cho mỗi HTTP Request"}, {"id": "C", "text": "Tồn tại suốt vòng đời của ứng dụng"}, {"id": "D", "text": "Tạo mới mỗi khi gọi hàm"}]', N'B'),
(48, 2, N'Trong ngôn ngữ C#, từ khóa ''var'' có ý nghĩa gì?', N'var là kiểu ngầm định (implicitly typed) được trình biên dịch tự động suy luận kiểu dữ liệu tại thời điểm biên dịch dựa vào giá trị khởi tạo.', N'EASY', 115, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.562', NULL, NULL, N'var, implicit typing, kiểu ngầm định, compile-time', N'MCQ', N'[{"id": "A", "text": "Biến động có thể đổi kiểu lúc runtime"}, {"id": "B", "text": "Trình biên dịch tự suy luận kiểu tại thời điểm biên dịch (Compile-time)"}, {"id": "C", "text": "Biến toàn cục truy cập mọi nơi"}, {"id": "D", "text": "Một đối tượng kiểu object"}]', N'B'),
(49, 2, N'Kiểu dữ liệu nào sau đây trong C# thuộc nhóm Value Type được lưu trên Stack?', N'struct, int, float, bool, enum thuộc nhóm Value Type, lưu trực tiếp giá trị trên Stack.', N'EASY', 116, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.563', NULL, NULL, N'Value Type, Reference Type, struct, class, Stack, Heap', N'MCQ', N'[{"id": "A", "text": "class"}, {"id": "B", "text": "string"}, {"id": "C", "text": "struct"}, {"id": "D", "text": "interface"}]', N'C'),
(50, 2, N'Thứ tự thực thi của các Middleware trong ASP.NET Core Request Pipeline được quyết định bởi yếu tố nào?', N'Thứ tự thực thi phụ thuộc hoàn toàn vào thứ tự gọi các hàm app.Use...() trong file cấu hình Program.cs.', N'EASY', 117, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.565', NULL, NULL, N'Middleware, Request Pipeline, Program.cs, thứ tự thực thi', N'MCQ', N'[{"id": "A", "text": "Tên theo thứ tự bảng chữ cái của middleware"}, {"id": "B", "text": "Thứ tự gọi app.Use...() được đăng ký trong Program.cs"}, {"id": "C", "text": "Mức độ ưu tiên do hệ điều hành cấp"}, {"id": "D", "text": "Thời điểm request gửi lên"}]', N'B');
INSERT INTO [interview_questions] ([id], [topic_id], [question_text], [sample_answer], [difficulty], [display_order], [is_active], [created_at], [updated_at], [created_by], [updated_by], [keywords], [question_type], [options_json], [correct_option_id]) VALUES
(51, 2, N'Nêu sự khác nhau giữa string và StringBuilder trong C#? Khi nào nên sử dụng StringBuilder?', N'string là đối tượng bất biến (immutable), mỗi thao tác nối chuỗi tạo ra một đối tượng mới trên Heap gây tốn bộ nhớ và kích hoạt GC. StringBuilder là đối tượng có thể thay đổi (mutable), quản lý bộ đệm động, nên dùng khi cần nối hoặc xử lý chuỗi trong vòng lặp nhiều lần.', N'EASY', 118, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.567', NULL, NULL, N'string, StringBuilder, immutable, mutable, tối ưu bộ nhớ, GC', N'WRITTEN', NULL, NULL),
(52, 2, N'Giải thích khái niệm Interface trong C# và lợi ích của việc lập trình hướng Interface (Programming to Interface)?', N'Interface là bản hợp đồng định nghĩa các phương thức/thuộc tính mà lớp dẫn xuất phải tuân thủ. Lợi ích: giảm tính phụ thuộc cứng giữa các module (Loose Coupling), tăng tính đa hình (Polymorphism), dễ dàng viết Unit Test bằng cách mock service.', N'EASY', 119, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.569', NULL, NULL, N'Interface, C#, loose coupling, polymorphism, unit test, dependency inversion', N'WRITTEN', NULL, NULL),
(53, 2, N'Phân biệt IEnumerable<T> và IQueryable<T> trong C# / LINQ? Trường hợp nào câu query được thực thi dưới Database?', N'IEnumerable<T> thực thi câu query in-memory trên client (LINQ to Objects). IQueryable<T> phân tích Expression Tree và dịch thành câu lệnh SQL để thực thi trực tiếp trên Database server (LINQ to Entities), giúp lọc dữ liệu ngay tại CSDL trước khi tải về RAM.', N'EASY', 120, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.570', NULL, NULL, N'IEnumerable, IQueryable, LINQ, in-memory, Expression Tree, SQL Server', N'WRITTEN', NULL, NULL),
(54, 2, N'Mục đích của file appsettings.json và cách đọc cấu hình theo mẫu Options Pattern (IOptions<T>) trong ASP.NET Core?', N'appsettings.json lưu trữ thông tin cấu hình ứng dụng (chuỗi kết nối, secret key, log level). Sử dụng Options Pattern giúp ánh xạ các khối JSON cấu hình thành các C# class có kiểu dữ liệu rõ ràng (strongly-typed), dễ inject qua IOptions<T> và dễ bảo trì.', N'EASY', 121, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.573', NULL, NULL, N'appsettings.json, Options Pattern, IOptions, strongly-typed configuration', N'WRITTEN', NULL, NULL),
(55, 2, N'Phân biệt từ khóa ''async'', ''await'' và kiểu ''Task'' trong lập trình bất đồng bộ C#?', N'Task đại diện cho một tác vụ bất đồng bộ đang thực thi hoặc sẽ hoàn tất trong tương lai. Từ khóa async đánh dấu một phương thức là bất đồng bộ. Từ khóa await dùng để tạm dừng thực thi phương thức cho đến khi Task hoàn thành mà không hề block luồng chính (thread pool).', N'EASY', 122, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.574', NULL, NULL, N'async, await, Task, asynchronous, non-blocking, ThreadPool', N'WRITTEN', NULL, NULL),
(56, 2, N'Trong Entity Framework Core, phương thức nào được khuyến nghị áp dụng cho các truy vấn chỉ đọc (read-only) để tăng hiệu năng và tiết kiệm RAM?', N'AsNoTracking() vô hiệu hóa tính năng Change Tracker của EF Core, giúp truy vấn đọc nhanh hơn và không lưu snapshot thực thể trong bộ nhớ.', N'MEDIUM', 123, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.576', NULL, NULL, N'AsNoTracking, EF Core, Change Tracker, Read-only', N'MCQ', N'[{"id": "A", "text": "AsNoTracking()"}, {"id": "B", "text": "AsTracking()"}, {"id": "C", "text": "Include()"}, {"id": "D", "text": "AsSplitQuery()"}]', N'A'),
(57, 2, N'Toán tử null-coalescing ''??'' và ''??='' trong C# có tác dụng gì?', N'Toán tử ''a ?? b'' trả về b nếu a null, ngược lại trả về a. Toán tử ''a ??= b'' gán giá trị b cho a nếu a đang có giá trị null.', N'MEDIUM', 124, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.578', NULL, NULL, N'null-coalescing, C#, ??, ??=', N'MCQ', N'[{"id": "A", "text": "So sánh giá trị tuyệt đối"}, {"id": "B", "text": "Trả về giá trị mặc định hoặc gán giá trị khi biến bị null"}, {"id": "C", "text": "Kiểm tra kiểu dữ liệu của biến"}, {"id": "D", "text": "Bắt ngoại lệ NullReferenceException"}]', N'B'),
(58, 2, N'Kiến trúc Repository Pattern kết hợp Unit of Work trong dự án ASP.NET Core mang lại lợi ích gì?', N'Tách biệt hoàn toàn tầng truy cập dữ liệu (Data Access) khỏi tầng nghiệp vụ (Business Logic), cho phép gom nhiều thao tác CRUD vào một transaction duy nhất qua DbContext.SaveChanges(), đồng thời giúp việc viết Unit Test bằng mock repository trở nên dễ dàng.', N'MEDIUM', 125, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.580', NULL, NULL, N'Repository Pattern, Unit of Work, DbContext, Decoupling, Unit Test', N'WRITTEN', NULL, NULL),
(59, 2, N'Trình bày cách xử lý ngoại lệ tập trung (Global Exception Handling) trong ASP.NET Core?', N'Tạo Custom Middleware (hoặc sử dụng IExceptionHandler từ .NET 8) bọc toàn bộ request pipeline trong khối try-catch. Khi có lỗi phát sinh chưa được xử lý, middleware bắt lại, ghi log ILogger, và serialize thông tin lỗi chuẩn hóa theo chuẩn RFC 7807 (ProblemDetails) trả về cho client.', N'MEDIUM', 126, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.581', NULL, NULL, N'Global Exception, Middleware, IExceptionHandler, ProblemDetails, RFC 7807, ILogger', N'WRITTEN', NULL, NULL),
(60, 2, N'Phân biệt Data Annotations và FluentValidation trong việc kiểm tra tính hợp lệ của Model trong ASP.NET Core?', N'Data Annotations sử dụng thuộc tính (attributes như [Required], [MaxLength]) trực tiếp trên DTO/Model, tiện lợi nhưng trộn lẫn rule với entity. FluentValidation tách biệt toàn bộ validation rules thành các class Validator độc lập, hỗ trợ logic kiểm tra phức tạp, validate bất đồng bộ và dễ viết unit test.', N'MEDIUM', 127, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.583', NULL, NULL, N'Data Annotations, FluentValidation, Model Validation, DTO, Separation of Concerns', N'WRITTEN', NULL, NULL),
(61, 2, N'Cơ chế CORS (Cross-Origin Resource Sharing) trong ASP.NET Core là gì và cách cấu hình an toàn?', N'CORS là cơ chế bảo mật của trình duyệt ngăn chặn web client ở origin này gọi API ở origin khác. Trong ASP.NET Core, cấu hình qua services.AddCors và app.UseCors() với các policy cụ thể (WithOrigins, WithMethods, WithHeaders) thay vì AllowAnyOrigin() trên môi trường production.', N'MEDIUM', 128, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.585', NULL, NULL, N'CORS, AddCors, UseCors, WithOrigins, Browser Security, Cross-Origin', N'WRITTEN', NULL, NULL),
(62, 2, N'Phân biệt các delegate chuẩn trong C#: Action<T>, Func<T>, và Predicate<T>?', N'Action<T> đại diện cho hàm có nhận tham số nhưng không trả về giá trị (void). Func<T, TResult> đại diện cho hàm có nhận tham số và trả về kết quả kiểu TResult. Predicate<T> là trường hợp đặc biệt của Func nhận tham số T và luôn trả về kiểu bool (thường dùng để lọc điều kiện).', N'MEDIUM', 129, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.587', NULL, NULL, N'Action, Func, Predicate, Delegate, C#, Lambda Expression', N'WRITTEN', NULL, NULL),
(63, 2, N'Quy trình làm việc với EF Core Migrations (Code-First) và cách xử lý cập nhật cơ sở dữ liệu?', N'Khi thay đổi entity model, lập trình viên chạy lệnh ''dotnet ef migrations add <Name>'' để tạo mã C# miêu tả thay đổi lược đồ DB (hàm Up và Down). Lệnh ''dotnet ef database update'' sẽ áp dụng các migration chưa chạy lên SQL Server và ghi nhận vào bảng __EFMigrationsHistory.', N'MEDIUM', 130, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.589', NULL, NULL, N'EF Core Migrations, Code-First, dotnet ef, Up, Down, __EFMigrationsHistory', N'WRITTEN', NULL, NULL),
(64, 2, N'So sánh cơ chế Caching trong ASP.NET Core: IMemoryCache vs IDistributedCache (Redis)? Khi nào nên chọn giải pháp nào?', N'IMemoryCache lưu dữ liệu trực tiếp trong RAM của process web hiện tại, tốc độ cực nhanh nhưng mất dữ liệu khi restart và không đồng bộ khi scale nhiều instance. IDistributedCache (Redis) lưu tập trung trên cụm server riêng, dữ liệu chia sẻ giữa tất cả các instance của hệ thống, phù hợp cho hệ thống microservices và load balancing.', N'MEDIUM', 131, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.590', NULL, NULL, N'IMemoryCache, IDistributedCache, Redis, In-memory, Distributed, Scaling', N'WRITTEN', NULL, NULL),
(65, 2, N'Action Filters trong ASP.NET Core là gì và các phương thức chính (OnActionExecuting, OnActionExecuted) được dùng cho mục đích gì?', N'Action Filters can thiệp vào trước và sau khi một Controller Action được gọi. OnActionExecuting cho phép kiểm tra ModelState, log tham số đầu vào hoặc ghi đè kết quả. OnActionExecuted cho phép chỉnh sửa kết quả trả về hoặc đo lường thời gian thực thi action.', N'MEDIUM', 132, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.592', NULL, NULL, N'ActionFilter, OnActionExecuting, OnActionExecuted, Filter Pipeline, ASP.NET Core', N'WRITTEN', NULL, NULL),
(66, 2, N'Khi sử dụng async/await trong C#, hiện tượng Deadlock thường phát sinh khi nào và cách khắc phục?', N'Deadlock xảy ra khi gọi đồng bộ trên Task (.Result hoặc .Wait()) trên môi trường có SynchronizationContext. Luồng chính bị chặn chờ Task hoàn thành, trong khi Task cần quay lại luồng chính để tiếp tục. Khắc phục bằng: luôn dùng async/await xuyên suốt (async all the way) hoặc cấu hình ConfigureAwait(false).', N'HARD', 133, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.594', NULL, NULL, N'Deadlock, async/await, SynchronizationContext, Task.Result, ConfigureAwait', N'MCQ', N'[{"id": "A", "text": "Khi tạo quá nhiều luồng Thread mới"}, {"id": "B", "text": "Khi gọi Task.Result hoặc Task.Wait() trên luồng có SynchronizationContext"}, {"id": "C", "text": "Khi câu truy vấn SQL chạy quá lâu"}, {"id": "D", "text": "Khi quên gọi Dispose trên DbContext"}]', N'B'),
(67, 2, N'Bộ thu gom rác (Garbage Collector) của .NET CLR phân chia các đối tượng thành những thế hệ (Generations) nào và Large Object Heap (LOH) được áp dụng khi nào?', N'GC chia thành Gen 0 (đối tượng mới tạo), Gen 1 (vùng đệm), Gen 2 (đối tượng sống lâu dài). LOH dành riêng cho các đối tượng có kích thước từ 85,000 bytes trở lên (như mảng lớn), mặc định ít bị dồn bộ nhớ (compaction) để tránh chi phí copy dữ liệu lớn.', N'HARD', 134, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.595', NULL, NULL, N'.NET GC, Generation 0, Generation 1, Generation 2, LOH, Large Object Heap, 85000 bytes', N'WRITTEN', NULL, NULL),
(68, 2, N'Mô tả chi tiết vòng đời của một HTTP Request khi đi qua toàn bộ kiến trúc ASP.NET Core Pipeline từ Kestrel đến Action và ngược lại?', N'Request tới Web Server (Kestrel) -> chuyển qua chuỗi Middleware được đăng ký theo thứ tự (Routing, Authentication, Authorization, Custom Middleware) -> Endpoint Routing chọn Action -> qua các Filter (Authorization, Resource, Model Binding, Action Filter) -> Action thực thi trả về IActionResult -> Result Filter -> Action Result sinh Response -> quay ngược lại các Middleware -> Kestrel gửi về Client.', N'HARD', 135, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.597', NULL, NULL, N'Request Pipeline, Kestrel, Middleware, Routing, Model Binding, Filters, IActionResult', N'WRITTEN', NULL, NULL),
(69, 2, N'Trình bày nguyên tắc thiết kế Clean Architecture trong dự án .NET (Domain, Application, Infrastructure, API)?', N'Tuân thủ Dependency Inversion Principle: Chiều phụ thuộc luôn hướng vào trong, Domain (Entities, Enums) là trung tâm không phụ thuộc vào bất kỳ công nghệ nào. Application chứa Business Logic/Use Cases và Interfaces. Infrastructure hiện thực các Interfaces (EF Core DBContext, Email, External API). Tầng API đóng vai trò Presentation và cấu hình DI.', N'HARD', 136, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.599', NULL, NULL, N'Clean Architecture, Domain, Application, Infrastructure, Dependency Inversion, Onion', N'WRITTEN', NULL, NULL),
(70, 2, N'Làm thế nào để xử lý xung đột đồng thời (Concurrency Conflict) trong EF Core bằng Concurrency Token / RowVersion?', N'Định nghĩa thuộc tính kiểu byte[] gắn annotation [Timestamp] hoặc cấu hình IsRowVersion() trong Fluent API. Khi update, EF Core sinh câu lệnh SQL ''WHERE Id = @id AND RowVersion = @originalRowVersion''. Nếu dòng đã bị transaction khác sửa trước đó, số dòng ảnh hưởng là 0 và EF Core ném DbUpdateConcurrencyException để xử lý retry hoặc thông báo.', N'HARD', 137, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.601', NULL, NULL, N'Concurrency, EF Core, RowVersion, Timestamp, DbUpdateConcurrencyException, Optimistic Concurrency', N'WRITTEN', NULL, NULL),
(71, 2, N'Cơ chế Background Processing trong .NET với BackgroundService và IHostedService hoạt động như thế nào?', N'BackgroundService (implement IHostedService) khởi chạy tác vụ nền song song với web server trong phương thức ExecuteAsync. Vì BackgroundService là Singleton nên không được inject trực tiếp Scoped Service (như DbContext), mà cần inject IServiceScopeFactory để tạo scope thủ công khi cần thao tác với database.', N'HARD', 138, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.603', NULL, NULL, N'BackgroundService, IHostedService, ExecuteAsync, IServiceScopeFactory, Scoped in Singleton', N'WRITTEN', NULL, NULL),
(72, 2, N'Trình bày cách triển khai Authentication và Authorization bằng JWT Bearer kết hợp Policy-based Authorization trong ASP.NET Core?', N'Cấu hình services.AddAuthentication với JwtBearerDefaults, xác thực token qua TokenValidationParameters (ValidateIssuer, ValidateAudience, ValidateLifetime, IssuerSigningKey). Phân quyền linh hoạt bằng Policy-based Authorization qua services.AddAuthorization và định nghĩa các Requirement cùng AuthorizationHandler tùy chỉnh.', N'HARD', 139, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.604', NULL, NULL, N'JWT Bearer, AddAuthentication, AddAuthorization, Policy-based, AuthorizationHandler, TokenValidationParameters', N'WRITTEN', NULL, NULL),
(73, 3, N'Hook nào trong React được sử dụng để khởi tạo và quản lý trạng thái (state) nội bộ của một Functional Component?', N'useState trả về một mảng gồm giá trị state hiện tại và hàm cập nhật state đó.', N'EASY', 140, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.606', NULL, NULL, N'useState, React Hooks, Component State', N'MCQ', N'[{"id": "A", "text": "useEffect"}, {"id": "B", "text": "useState"}, {"id": "C", "text": "useContext"}, {"id": "D", "text": "useRef"}]', N'B'),
(74, 3, N'Trong TypeScript, kiểu dữ liệu nào đại diện cho một hàm không trả về bất kỳ giá trị nào?', N'Kiểu void biểu thị rằng hàm thực thi các câu lệnh nhưng không trả về giá trị (return undefined).', N'EASY', 141, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.607', NULL, NULL, N'void, TypeScript, return type', N'MCQ', N'[{"id": "A", "text": "null"}, {"id": "B", "text": "undefined"}, {"id": "C", "text": "void"}, {"id": "D", "text": "never"}]', N'C'),
(75, 3, N'Khi render một danh sách các phần tử bằng hàm .map() trong React, thuộc tính ''key'' có vai trò quan trọng gì?', N'Thuộc tính key là định danh duy nhất giúp thuật toán Virtual DOM Diffing nhận biết phần tử nào đã được thêm, sửa hoặc xóa để cập nhật chính xác mà không phải re-render lại toàn bộ danh sách.', N'EASY', 142, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.609', NULL, NULL, N'key prop, React, Virtual DOM, Diffing, reconciliation', N'MCQ', N'[{"id": "A", "text": "Để tạo chỉ mục CSS cho phần tử"}, {"id": "B", "text": "Giúp thuật toán Virtual DOM phân biệt và tái sử dụng đúng phần tử khi danh sách thay đổi"}, {"id": "C", "text": "Để lưu dữ liệu vào localStorage"}, {"id": "D", "text": "Bắt buộc cho trình duyệt hiển thị đúng thứ tự"}]', N'B');
INSERT INTO [interview_questions] ([id], [topic_id], [question_text], [sample_answer], [difficulty], [display_order], [is_active], [created_at], [updated_at], [created_by], [updated_by], [keywords], [question_type], [options_json], [correct_option_id]) VALUES
(76, 3, N'Phân biệt sự khác nhau cơ bản giữa ''props'' và ''state'' trong React?', N'Props là dữ liệu được truyền từ component cha xuống component con, component con chỉ đọc (read-only / immutable). State là dữ liệu nội bộ do chính component đó quản lý và có thể thay đổi trong suốt vòng đời của nó.', N'EASY', 143, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.610', NULL, NULL, N'props, state, React, immutable, re-render, component', N'WRITTEN', NULL, NULL),
(77, 3, N'Nêu sự khác biệt giữa ''type'' và ''interface'' trong TypeScript? Khi nào nên ưu tiên dùng loại nào?', N'Interface có thể mở rộng (declaration merging) và kế thừa linh hoạt (extends), rất phù hợp khi định nghĩa cấu trúc đối tượng và contracts. Type alias mạnh về tạo Union Types, Intersection, Tuples và các kiểu nguyên thủy kết hợp. Nên dùng Interface cho định nghĩa object/props và Type cho unions/utilities.', N'EASY', 144, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.612', NULL, NULL, N'type, interface, TypeScript, declaration merging, union types', N'WRITTEN', NULL, NULL),
(78, 3, N'Giải thích cơ chế Virtual DOM của React và cách nó giúp tối ưu hóa hiệu năng giao diện?', N'Virtual DOM là bản sao nhẹ (JavaScript object) của Real DOM trên RAM. Khi state thay đổi, React tạo cây Virtual DOM mới, so sánh với cây cũ (Diffing Algorithm) để tìm ra các thay đổi tối thiểu, sau đó gộp lại và chỉ cập nhật đúng các node đó lên Real DOM (Reconciliation / Batching).', N'EASY', 145, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.614', NULL, NULL, N'Virtual DOM, Real DOM, Diffing Algorithm, Reconciliation, Batching', N'WRITTEN', NULL, NULL),
(79, 3, N'Hook useEffect hoạt động như thế nào? Nêu ý nghĩa của mảng phụ thuộc (dependency array)?', N'useEffect dùng để thực thi các side-effects (gọi API, subscription, thao tác DOM). Nếu dependency array rỗng ([]), effect chỉ chạy 1 lần khi component mount. Nếu chứa biến ([a, b]), effect chạy lại khi giá trị biến thay đổi. Nếu không truyền mảng phụ thuộc, effect chạy sau mỗi lần re-render.', N'EASY', 146, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.616', NULL, NULL, N'useEffect, side effects, dependency array, mounting, re-render', N'WRITTEN', NULL, NULL),
(80, 3, N'Phân biệt Controlled Component và Uncontrolled Component trong việc xử lý Form trên React?', N'Controlled Component lưu trữ giá trị của ô input trực tiếp trong React state (thông qua value và onChange), giúp kiểm soát validation tức thì. Uncontrolled Component để DOM tự quản lý giá trị của thẻ input và lập trình viên truy cập giá trị bằng hook useRef khi cần submit.', N'EASY', 147, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.617', NULL, NULL, N'Controlled Component, Uncontrolled Component, useRef, useState, Form', N'WRITTEN', NULL, NULL),
(81, 3, N'Hook nào trong React được sử dụng để ghi nhớ (memoize) kết quả của một phép tính toán phức tạp, tránh tính lại mỗi khi component re-render?', N'useMemo lưu lại kết quả tính toán và chỉ tính lại khi một trong các dependencies thay đổi.', N'MEDIUM', 148, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.619', NULL, NULL, N'useMemo, memoize, performance, re-render', N'MCQ', N'[{"id": "A", "text": "useCallback"}, {"id": "B", "text": "useMemo"}, {"id": "C", "text": "useRef"}, {"id": "D", "text": "useReducer"}]', N'B'),
(82, 3, N'Cơ chế nào trong React cho phép chia sẻ dữ liệu cho toàn bộ cây component con mà không cần truyền props qua từng cấp (tránh prop-drilling)?', N'React Context API cho phép tạo Provider và Consumer (hoặc hook useContext) để truyền state toàn cục xuống mọi component con.', N'MEDIUM', 149, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.620', NULL, NULL, N'Context API, useContext, prop-drilling, React Provider', N'MCQ', N'[{"id": "A", "text": "Redux Saga"}, {"id": "B", "text": "React Context (createContext & useContext)"}, {"id": "C", "text": "React Fragment"}, {"id": "D", "text": "Higher-Order Component"}]', N'B'),
(83, 3, N'Toán tử ''as const'' trong TypeScript có tác dụng gì khi khai báo một mảng hoặc object?', N'as const chuyển toàn bộ thuộc tính của object hoặc phần tử mảng thành dạng ''readonly'' và ép kiểu dữ liệu về kiểu hằng số (literal types) chính xác.', N'MEDIUM', 150, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.622', NULL, NULL, N'as const, TypeScript, readonly, literal types', N'MCQ', N'[{"id": "A", "text": "Biến đối tượng thành class tĩnh"}, {"id": "B", "text": "Chuyển toàn bộ thuộc tính thành readonly và ép kiểu literal types cụ thể"}, {"id": "C", "text": "Tự động xuất ra file JSON"}, {"id": "D", "text": "Cho phép thêm thuộc tính động lúc runtime"}]', N'B'),
(84, 3, N'Phân biệt sự khác nhau giữa useCallback và useMemo? Nêu ví dụ khi nào useCallback thực sự mang lại hiệu quả?', N'useMemo ghi nhớ giá trị trả về của một hàm. useCallback ghi nhớ chính bản thân định nghĩa của hàm đó để tránh tạo tham chiếu hàm mới mỗi lần re-render. useCallback chỉ thực sự có ích khi truyền hàm đó xuống component con đã được bọc bằng React.memo hoặc dùng làm dependency của useEffect khác.', N'MEDIUM', 151, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.624', NULL, NULL, N'useCallback, useMemo, React.memo, tham chiếu hàm, performance', N'WRITTEN', NULL, NULL),
(85, 3, N'Trình bày cách quản lý Server State bằng thư viện TanStack Query (React Query) và ưu điểm so với việc dùng useEffect + useState?', N'React Query tự động hóa việc caching dữ liệu server, deduplication (tránh gọi trùng lặp request), background refetching khi focus cửa sổ, quản lý trạng thái loading/error, và cung cấp query invalidation sau mutation. Trong khi dùng useEffect truyền thống phải tự viết logic cồng kềnh và dễ gặp lỗi race condition.', N'MEDIUM', 152, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.625', NULL, NULL, N'TanStack Query, React Query, cacheTime, staleTime, Invalidation, Server State', N'WRITTEN', NULL, NULL),
(86, 3, N'Khái niệm Custom Hook trong React là gì? Khi nào cần tạo Custom Hook và nêu một trường hợp thực tế bạn đã xây dựng?', N'Custom Hook là một hàm JavaScript có tiền tố ''use...'' cho phép gom nhóm và tái sử dụng logic chứa stateful hooks (như useState, useEffect). Ví dụ: hook useDebounce để hoãn tìm kiếm, useLocalStorage để đồng bộ state với LocalStorage, hoặc useMediaQuery để nhận biết kích thước màn hình responsive.', N'MEDIUM', 153, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.628', NULL, NULL, N'Custom Hook, useDebounce, reusable logic, separation of concerns', N'WRITTEN', NULL, NULL),
(87, 3, N'Generic Types trong TypeScript là gì và tại sao chúng lại quan trọng trong việc xây dựng các hàm / component tái sử dụng?', N'Generics cho phép định nghĩa các hàm, interface, class hoạt động với nhiều kiểu dữ liệu khác nhau mà vẫn giữ nguyên được tính an toàn kiểu (Type Safety). Thay vì dùng kiểu ''any'', Generics ghi nhớ kiểu dữ liệu truyền vào và kiểm tra lỗi ngay tại thời điểm biên dịch.', N'MEDIUM', 154, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.629', NULL, NULL, N'Generics, TypeScript, Type Safety, reusable components, compile-time check', N'WRITTEN', NULL, NULL),
(88, 3, N'So sánh giải pháp quản lý Form bằng thư viện React Hook Form kết hợp Zod với giải pháp dùng useState truyền thống?', N'React Hook Form sử dụng Uncontrolled Component giúp giảm thiểu tối đa số lần re-render của toàn bộ form khi người dùng gõ từng ký tự. Kết hợp Zod schema giúp định nghĩa luật validate strongly-typed, tách biệt logic kiểm tra khỏi giao diện và tự động suy luận kiểu dữ liệu TypeScript (z.infer).', N'MEDIUM', 155, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.631', NULL, NULL, N'React Hook Form, Zod, Validation, Re-render, Schema validation, z.infer', N'WRITTEN', NULL, NULL),
(89, 3, N'Trình bày kiến trúc định tuyến bằng React Router (Nested Routes, Dynamic Parameters, Protected Route)?', N'React Router quản lý điều hướng trên client không reload trang. Nested Routes cho phép lồng ghép giao diện con qua <Outlet />. Dynamic params truy cập qua hook useParams(). Protected Route bọc các trang nhạy cảm để kiểm tra auth token; nếu chưa đăng nhập sẽ chuyển hướng (Navigate) sang trang Login.', N'MEDIUM', 156, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.633', NULL, NULL, N'React Router, Outlet, useParams, Protected Route, Navigate, SPA Routing', N'WRITTEN', NULL, NULL),
(90, 3, N'Làm thế nào để áp dụng kỹ thuật Code-Splitting và Lazy Loading trong React bằng React.lazy và Suspense?', N'Sử dụng React.lazy(() => import(''./HeavyComponent'')) để tách bundle component thành các file JS nhỏ riêng biệt và chỉ tải khi người dùng thực sự điều hướng đến. Bao bọc bằng <Suspense fallback={<LoadingSpinner />}> để hiển thị giao diện chờ trong lúc trình duyệt tải file script qua mạng.', N'MEDIUM', 157, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.634', NULL, NULL, N'React.lazy, Suspense, Code-Splitting, Webpack bundle, lazy loading, performance', N'WRITTEN', NULL, NULL),
(91, 3, N'Giải thích cơ chế Cleanup Function trong useEffect và nêu ví dụ khi nào bắt buộc phải có cleanup?', N'Hàm cleanup được trả về từ callback của useEffect, chạy trước khi effect chạy lại hoặc khi component unmount. Bắt buộc dùng để: hủy timer (clearInterval, clearTimeout), ngắt lắng nghe sự kiện (removeEventListener), đóng kết nối WebSocket hoặc hủy HTTP request (AbortController) để tránh rò rỉ bộ nhớ.', N'MEDIUM', 158, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.636', NULL, NULL, N'Cleanup Function, useEffect, unmount, Memory Leak, AbortController, removeEventListener', N'WRITTEN', NULL, NULL),
(92, 3, N'Trong React 18, các tính năng đồng thời (Concurrent Features) như startTransition hoặc useDeferredValue giải quyết bài toán gì?', N'Phân tách các cập nhật khẩn cấp (như gõ phím) và cập nhật không khẩn cấp (như render danh sách kết quả tìm kiếm lớn) để tránh lag giao diện.', N'HARD', 159, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.637', NULL, NULL, N'React 18, Concurrent Mode, startTransition, useDeferredValue, non-blocking UI', N'MCQ', N'[{"id": "A", "text": "Giúp component giao tiếp trực tiếp với cơ sở dữ liệu"}, {"id": "B", "text": "Phân tách cập nhật khẩn cấp và không khẩn cấp để giao diện không bị đơ giật"}, {"id": "C", "text": "Tự động tải lại trang khi có lỗi"}, {"id": "D", "text": "Bảo vệ API key không bị lộ trên client"}]', N'B'),
(93, 3, N'Thuật toán so sánh (Diffing Algorithm) của React Virtual DOM đạt độ phức tạp thời gian xấp xỉ là bao nhiêu nhờ các giả định tối ưu?', N'Nhờ 2 giả định thực nghiệm (2 phần tử khác kiểu tạo cây khác nhau và dùng thuộc tính key), React giảm độ phức tạp từ O(n^3) xuống O(n).', N'HARD', 160, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.639', NULL, NULL, N'Diffing Algorithm, Virtual DOM, O(n), heuristic, Reconciliation', N'MCQ', N'[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(log n)"}, {"id": "C", "text": "O(n)"}, {"id": "D", "text": "O(n^2)"}]', N'C'),
(94, 3, N'Trình bày các nguyên nhân phổ biến gây ra Memory Leak trong ứng dụng React Single Page Application (SPA) và cách phòng tránh?', N'Nguyên nhân: Đăng ký event listener trên window/document hoặc WebSocket mà quên cleanup khi unmount; timer (setInterval) tiếp tục chạy ngầm; cập nhật state trên unmounted component sau khi async API hoàn tất. Phòng tránh: Luôn viết return cleanup function trong useEffect, dùng AbortController để cancel fetch, và hủy subscriptions.', N'HARD', 161, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.641', NULL, NULL, N'Memory Leak, React SPA, Unmounted component, Event Listener, AbortController, cleanup', N'WRITTEN', NULL, NULL),
(95, 3, N'Trình bày các Utility Types nâng cao trong TypeScript: Partial, Required, Pick, Omit, Record và ReturnType?', N'Partial<T> biến mọi thuộc tính thành optional (?). Required<T> biến mọi thuộc tính thành bắt buộc. Pick<T, K> trích xuất tập hợp các thuộc tính được chọn. Omit<T, K> loại bỏ các thuộc tính được chỉ định. Record<K, T> tạo object type với danh sách keys K và giá trị T. ReturnType<T> lấy kiểu trả về của một hàm.', N'HARD', 162, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.642', NULL, NULL, N'Utility Types, TypeScript, Partial, Pick, Omit, Record, ReturnType', N'WRITTEN', NULL, NULL),
(96, 3, N'So sánh SSR (Server-Side Rendering), CSR (Client-Side Rendering) và SSG (Static Site Generation)? Khi nào nên chọn mô hình nào?', N'CSR tải HTML rỗng rồi JS render nội dung tại trình duyệt (tốt cho Dashboard nội bộ, tương tác nhanh, nhưng SEO kém). SSR render HTML đầy đủ trên server mỗi request (tốt cho trang tin tức/thương mại điện tử cần SEO và dữ liệu thay đổi liên tục). SSG render sẵn HTML lúc build (cực nhanh, an toàn, phù hợp blog, tài liệu, landing page).', N'HARD', 163, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.644', NULL, NULL, N'SSR, CSR, SSG, Next.js, SEO, First Contentful Paint', N'WRITTEN', NULL, NULL),
(97, 3, N'Làm thế nào để tối ưu hóa hiệu năng render danh sách cực lớn (hàng chục ngàn dòng) trong React bằng kỹ thuật Virtualization (Windowing)?', N'Áp dụng thư viện react-window hoặc @tanstack/react-virtual. Kỹ thuật này chỉ render lên DOM các phần tử đang nằm trong vùng nhìn thấy của màn hình (viewport) cộng thêm một buffer nhỏ, tính toán vị trí bằng CSS absolute/transform. Nhờ đó giữ số lượng DOM node cố định (vài chục node) thay vì hàng chục ngàn node, tránh làm đơ trình duyệt.', N'HARD', 164, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.646', NULL, NULL, N'Virtualization, Windowing, react-window, tanstack-virtual, DOM optimization, viewport', N'WRITTEN', NULL, NULL),
(98, 3, N'So sánh giải pháp quản lý trạng thái Client State phức tạp bằng Redux Toolkit so với Zustand? Đánh giá về boilerplate và hiệu năng?', N'Redux Toolkit chuẩn hóa kiến trúc với Slices, Actions, Reducers, immutable updates qua Immer và DevTools tuyệt vời, nhưng cấu trúc file tương đối nặng (boilerplate). Zustand là giải pháp tối giản, không cần bọc Provider xung quanh ứng dụng, hỗ trợ selector subscription để chỉ re-render component khi phần state được chọn thay đổi, code ngắn gọn và hiệu năng cao.', N'HARD', 165, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.648', NULL, NULL, N'Redux Toolkit, Zustand, State Management, Boilerplate, Selectors, Re-render', N'WRITTEN', NULL, NULL),
(99, 4, N'Trong JavaScript, điểm khác biệt chính giữa toán tử so sánh lỏng lẻo ''=='' và so sánh nghiêm ngặt ''==='' là gì?', N'Toán tử ''=='' tự động ép kiểu dữ liệu (type coercion) trước khi so sánh, trong khi ''==='' so sánh cả giá trị và kiểu dữ liệu mà không ép kiểu.', N'EASY', 166, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.650', NULL, NULL, N'so sánh, type coercion, JavaScript, ==, ===', N'MCQ', N'[{"id": "A", "text": "Toán tử === chạy chậm hơn =="}, {"id": "B", "text": "Toán tử === so sánh cả giá trị và kiểu dữ liệu mà không ép kiểu ngầm định"}, {"id": "C", "text": "Toán tử == chỉ dùng cho chuỗi"}, {"id": "D", "text": "Toán tử === chỉ dùng cho số"}]', N'B'),
(100, 4, N'Kết quả của biểu thức ''typeof null'' trong JavaScript là gì?', N'typeof null trả về ''object'' do lỗi thiết kế lịch sử từ phiên bản đầu tiên của JavaScript và được giữ lại để đảm bảo tính tương thích ngược.', N'EASY', 167, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.652', NULL, NULL, N'typeof, null, object, JavaScript quirk', N'MCQ', N'[{"id": "A", "text": "''null''"}, {"id": "B", "text": "''undefined''"}, {"id": "C", "text": "''object''"}, {"id": "D", "text": "''boolean''"}]', N'C');
INSERT INTO [interview_questions] ([id], [topic_id], [question_text], [sample_answer], [difficulty], [display_order], [is_active], [created_at], [updated_at], [created_by], [updated_by], [keywords], [question_type], [options_json], [correct_option_id]) VALUES
(101, 4, N'Trong Node.js, hàm nào theo chuẩn CommonJS được dùng để import module từ file khác hoặc package bên ngoài?', N'Hàm require() dùng trong hệ thống module CommonJS để nạp file và thư viện.', N'EASY', 168, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.653', NULL, NULL, N'require, CommonJS, Node.js module', N'MCQ', N'[{"id": "A", "text": "import()"}, {"id": "B", "text": "require()"}, {"id": "C", "text": "include()"}, {"id": "D", "text": "load()"}]', N'B'),
(102, 4, N'Lệnh nào sau đây trong npm dùng để cài đặt một package và lưu vào mục ''devDependencies'' của file package.json?', N'Cờ -D hoặc --save-dev lưu package vào devDependencies (chỉ dùng cho môi trường dev như testing, build tools).', N'EASY', 169, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.655', NULL, NULL, N'npm, devDependencies, package.json, npm install', N'MCQ', N'[{"id": "A", "text": "npm install --save-prod"}, {"id": "B", "text": "npm install -D (hoặc --save-dev)"}, {"id": "C", "text": "npm install -g"}, {"id": "D", "text": "npm install --peer"}]', N'B'),
(103, 4, N'Khái niệm Closure trong JavaScript là gì và ứng dụng thực tế của nó?', N'Closure là khả năng của một hàm ghi nhớ và truy cập vào phạm vi biến (lexical scope) của hàm cha bao bọc nó, ngay cả khi hàm cha đã thực thi xong và kết thúc. Ứng dụng: tạo biến private (tính đóng gói), tạo hàm factory, và xử lý trong callbacks/currying.', N'EASY', 170, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.657', NULL, NULL, N'Closure, Lexical Scope, Private Variables, JavaScript', N'WRITTEN', NULL, NULL),
(104, 4, N'Phân biệt sự khác nhau giữa ''var'', ''let'' và ''const'' trong JavaScript (về phạm vi scope, hoisting và gán lại giá trị)?', N'var có function scope, bị hoisting lên đầu và khởi tạo bằng undefined, cho phép gán lại và khai báo lại. let và const có block scope ({}), cũng bị hoisting nhưng nằm trong Temporal Dead Zone (TDZ) trước khi được định nghĩa. let cho phép gán lại giá trị, const không cho phép gán lại tham chiếu sau khi khởi tạo.', N'EASY', 171, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.658', NULL, NULL, N'var, let, const, block scope, hoisting, Temporal Dead Zone, TDZ', N'WRITTEN', NULL, NULL),
(105, 4, N'Nêu các điểm khác biệt chính giữa Arrow Function và Regular Function trong JavaScript?', N'Arrow Function không có con trỏ ''this'' riêng mà kế thừa ''this'' từ phạm vi bao quanh (lexical this); không có đối tượng ''arguments''; không thể dùng làm hàm khởi tạo constructor với từ khóa ''new''; và không có thuộc tính ''prototype''.', N'EASY', 172, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.659', NULL, NULL, N'Arrow Function, Regular Function, this, lexical this, arguments, constructor', N'WRITTEN', NULL, NULL),
(106, 4, N'Nêu sự khác nhau giữa cơ chế đồng bộ (synchronous) và bất đồng bộ (asynchronous) trong môi trường thực thi của Node.js?', N'Mã đồng bộ thực thi tuần tự từ trên xuống dưới, tác vụ tốn thời gian (như đọc file fs.readFileSync) sẽ chặn đứng luồng thực thi (block the thread). Mã bất đồng bộ (như fs.readFile, gọi DB) gửi tác vụ cho hệ điều hành/libuv xử lý nền và tiếp tục chạy các lệnh tiếp theo; khi hoàn thành callback sẽ được đưa vào Event Loop xử lý.', N'EASY', 173, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.661', NULL, NULL, N'synchronous, asynchronous, blocking, non-blocking, libuv, Node.js', N'WRITTEN', NULL, NULL),
(107, 4, N'Giải thích vòng đời của Promise (Pending, Fulfilled, Rejected) và cú pháp async/await?', N'Promise đại diện cho kết quả của một tác vụ bất đồng bộ với 3 trạng thái: Pending (đang chờ), Fulfilled (thành công, gọi .then()), Rejected (thất bại, gọi .catch()). Cú pháp async/await là cú pháp cú pháp đường (syntactic sugar) giúp viết mã bất đồng bộ trông giống như mã đồng bộ, xử lý lỗi trực quan bằng try/catch.', N'EASY', 174, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.662', NULL, NULL, N'Promise, Pending, Fulfilled, Rejected, async/await, try/catch', N'WRITTEN', NULL, NULL),
(108, 4, N'Trong kiến trúc Express.js, một Middleware thông thường nhận vào những tham số nào để điều khiển luồng xử lý?', N'Middleware chuẩn của Express nhận vào 3 tham số: req (Request), res (Response), và next (hàm chuyển giao điều khiển cho middleware tiếp theo).', N'MEDIUM', 175, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.664', NULL, NULL, N'Middleware, Express.js, req, res, next', N'MCQ', N'[{"id": "A", "text": "(req, res)"}, {"id": "B", "text": "(req, res, next)"}, {"id": "C", "text": "(err, req, res)"}, {"id": "D", "text": "(app, server)"}]', N'B'),
(109, 4, N'Trong Node.js Event Loop, hàm ''process.nextTick()'' có mức độ ưu tiên như thế nào so với ''setImmediate()''?', N'process.nextTick() được đưa vào Microtask Queue và thực thi ngay lập tức khi phase hiện tại kết thúc, trước bất kỳ phase nào khác của Event Loop bao gồm cả setImmediate().', N'MEDIUM', 176, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.665', NULL, NULL, N'process.nextTick, setImmediate, Event Loop, Microtask Queue', N'MCQ', N'[{"id": "A", "text": "Chạy sau setImmediate()"}, {"id": "B", "text": "Chạy ngay sau khi phase hiện tại hoàn tất, trước mọi timer và I/O callbacks"}, {"id": "C", "text": "Chạy cùng thời điểm với setTimeout(0)"}, {"id": "D", "text": "Chỉ chạy khi CPU rảnh rỗi"}]', N'B'),
(110, 4, N'Trình bày chi tiết cơ chế hoạt động của Event Loop trong Node.js (Call Stack, Libuv, Microtask Queue vs Macrotask Queue)?', N'Node.js là single-threaded về mặt JS execution. Các tác vụ đồng bộ chạy trên Call Stack. Tác vụ bất đồng bộ (I/O, network) được chuyển cho C++ Libuv Thread Pool xử lý. Khi hoàn thành, callback được xếp vào các hàng đợi: Microtask Queue (process.nextTick, Promise callbacks) có độ ưu tiên cao nhất, chạy cạn kiệt trước khi chuyển sang các Phase của Macrotask Queue (Timers, I/O Polling, Check/setImmediate, Close).', N'MEDIUM', 177, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.667', NULL, NULL, N'Event Loop, Libuv, Call Stack, Microtask Queue, Macrotask Queue, Timers, Check phase', N'WRITTEN', NULL, NULL),
(111, 4, N'Kiến trúc Middleware trong Express.js là gì và các bước xây dựng một Auth Middleware kiểm tra JWT?', N'Middleware là các hàm trung gian nằm trong chuỗi xử lý request. Auth Middleware: Lấy chuỗi Bearer Token từ header ''Authorization''; kiểm tra sự tồn tại; sử dụng thư viện jsonwebtoken (jwt.verify) với Secret Key. Nếu hợp lệ, gán thông tin payload vào req.user và gọi next(); nếu không hợp lệ hoặc hết hạn, trả về response status 401 Unauthorized.', N'MEDIUM', 178, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.668', NULL, NULL, N'Express Middleware, JWT, jsonwebtoken, req.user, next(), 401 Unauthorized', N'WRITTEN', NULL, NULL),
(112, 4, N'Khái niệm Streams và Buffer trong Node.js? Tại sao nên sử dụng Streams khi đọc ghi file có dung lượng lớn?', N'Buffer là vùng nhớ tạm thời trên RAM để lưu trữ dữ liệu nhị phân thô. Stream là cơ chế xử lý dữ liệu theo từng khối nhỏ (chunks) liên tục. Đọc file lớn bằng fs.readFile sẽ load toàn bộ file vào RAM gây tràn bộ nhớ (OOM). Dùng Stream (fs.createReadStream) kết hợp .pipe() giúp truyền dữ liệu theo từng luồng nhỏ, dung lượng RAM tiêu thụ luôn ở mức tối thiểu và ổn định.', N'MEDIUM', 179, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.670', NULL, NULL, N'Streams, Buffer, chunks, fs.createReadStream, pipe, Out Of Memory, RAM', N'WRITTEN', NULL, NULL),
(113, 4, N'So sánh việc thao tác cơ sở dữ liệu bằng Mongoose (MongoDB) với Prisma ORM (PostgreSQL/MySQL)?', N'Mongoose là ODM dành cho tài liệu NoSQL MongoDB, định nghĩa Schema linh hoạt, phù hợp cấu trúc dữ liệu bán cấu trúc lồng nhau. Prisma là ORM hiện đại cho SQL (và MongoDB), sử dụng file schema.prisma để tự động sinh mã Client TypeScript strongly-typed, hỗ trợ autocomplete thông minh và tự động tạo migrations cho CSDL quan hệ.', N'MEDIUM', 180, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.672', NULL, NULL, N'Mongoose, Prisma ORM, MongoDB, PostgreSQL, Type-safe, Schema', N'WRITTEN', NULL, NULL),
(114, 4, N'Cơ chế EventEmitter trong Node.js hoạt động như thế nào và cách ứng dụng mô hình Publish/Subscribe (Pub-Sub)?', N'Lớp EventEmitter thuộc module ''events'' cho phép tạo và quản lý các sự kiện tùy chỉnh. Sử dụng emitter.on(''eventName'', callback) để đăng ký lắng nghe (Subscriber) và emitter.emit(''eventName'', data) để phát tín hiệu (Publisher). Giúp tách rời (decouple) các module trong hệ thống như gửi email thông báo sau khi đặt hàng thành công.', N'MEDIUM', 181, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.673', NULL, NULL, N'EventEmitter, Publish Subscribe, Pub-Sub, emit, on, events module', N'WRITTEN', NULL, NULL),
(115, 4, N'Trình bày các giải pháp bảo mật thiết yếu cho ứng dụng Node.js Express API (sử dụng Helmet, Cors, Rate-limit)?', N'Sử dụng Helmet để tự động cấu hình các HTTP response headers an toàn (chống clickjacking, X-XSS-Protection, HSTS). Sử dụng express-rate-limit để giới hạn số lượng request từ một địa chỉ IP trong khoảng thời gian nhất định (chống brute-force và DoS). Cấu hình CORS chặt chẽ chỉ cho phép domain tin cậy.', N'MEDIUM', 182, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.675', NULL, NULL, N'Helmet, express-rate-limit, CORS, Security Headers, Brute-force, Express API', N'WRITTEN', NULL, NULL),
(116, 4, N'Cách xây dựng cơ chế xử lý lỗi tập trung (Centralized Error Handling) trong ứng dụng Express.js?', N'Tạo custom Error class (VD: AppError kế thừa Error chứa statusCode, isOperational). Sử dụng Middleware xử lý lỗi có 4 tham số (err, req, res, next) đặt ở cuối cùng của pipeline. Tự động bắt lỗi từ các hàm async bằng wrapper function hoặc thư viện express-async-errors để không bị crash server.', N'MEDIUM', 183, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.677', NULL, NULL, N'Error Handling, Express, 4 parameters, AppError, express-async-errors, StatusCode', N'WRITTEN', NULL, NULL),
(117, 4, N'Phân biệt Cookie, LocalStorage và SessionStorage khi lưu trữ dữ liệu tại trình duyệt web trong ứng dụng Fullstack?', N'LocalStorage lưu không giới hạn thời gian (dung lượng ~5MB), chỉ xóa bằng mã JS hoặc người dùng xóa cache. SessionStorage chỉ tồn tại trong tab trình duyệt hiện tại và bị xóa khi đóng tab. Cookie (dung lượng ~4KB) được tự động gửi kèm mỗi HTTP request lên server; nếu gắn cờ HttpOnly và Secure thì an toàn chống XSS.', N'MEDIUM', 184, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.679', NULL, NULL, N'Cookie, LocalStorage, SessionStorage, HttpOnly, XSS, Browser Storage', N'WRITTEN', NULL, NULL),
(118, 4, N'Module nào trong Node.js cho phép tận dụng tối đa hệ thống CPU đa nhân (multi-core) bằng cách tạo ra các worker process con chạy chung port?', N'Cluster module cho phép phân nhánh (fork) tiến trình chính thành nhiều worker process con, chia sẻ chung cổng mạng để cân bằng tải trên các core CPU.', N'HARD', 185, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.680', NULL, NULL, N'Cluster module, multi-core, worker processes, scaling', N'MCQ', N'[{"id": "A", "text": "V8 Engine Module"}, {"id": "B", "text": "Cluster Module"}, {"id": "C", "text": "Child Process Exec"}, {"id": "D", "text": "HTTP Agent"}]', N'B'),
(119, 4, N'Sự cố ''Unhandled Promise Rejection'' trong các phiên bản Node.js hiện đại nếu không được bắt sẽ gây ra hành vi gì cho tiến trình?', N'Từ Node.js 15+, Unhandled Promise Rejection mặc định sẽ lập tức dừng tiến trình (exit process with non-zero code) để tránh việc ứng dụng chạy ở trạng thái bất định.', N'HARD', 186, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.682', NULL, NULL, N'Unhandled Promise Rejection, Node.js process exit, error handling', N'MCQ', N'[{"id": "A", "text": "Chỉ in cảnh báo ra console và tiếp tục chạy"}, {"id": "B", "text": "Chấm dứt tiến trình Node.js ngay lập tức (Process Crash)"}, {"id": "C", "text": "Tự động thử lại request 3 lần"}, {"id": "D", "text": "Gửi email cảnh báo cho quản trị viên"}]', N'B'),
(120, 4, N'Phân biệt Worker Threads và Child Process trong Node.js? Khi nào nên chọn giải pháp nào cho bài toán xử lý tác vụ nặng (CPU-intensive)?', N'Child Process tạo ra một tiến trình hệ điều hành độc lập hoàn toàn, có không gian bộ nhớ riêng biệt và giao tiếp qua IPC (thích hợp chạy script bên ngoài). Worker Threads chạy trong cùng một tiến trình, chia sẻ chung bộ nhớ thông qua SharedArrayBuffer, tiêu tốn ít tài nguyên hơn, rất thích hợp cho tác vụ tính toán CPU-intensive như nén ảnh, mã hóa dữ liệu phức tạp.', N'HARD', 187, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.684', NULL, NULL, N'Worker Threads, Child Process, CPU-intensive, SharedArrayBuffer, IPC, multi-threading', N'WRITTEN', NULL, NULL),
(121, 4, N'Trình bày nguyên lý và giải pháp phòng chống các lỗ hổng bảo mật phổ biến trong ứng dụng Fullstack: SQL/NoSQL Injection, XSS, và CSRF?', N'SQL Injection: Dùng Parameterized Query hoặc ORM. NoSQL Injection: Kiểm tra type tham số, tránh truyền trực tiếp object $gt/$ne từ body. XSS (Cross-Site Scripting): Thoát mã (escape HTML), dùng Content Security Policy (CSP), lưu trữ token trong HttpOnly Cookie. CSRF: Dùng SameSite Cookie attribute hoặc CSRF tokens cho các request thay đổi trạng thái.', N'HARD', 188, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.685', NULL, NULL, N'SQL Injection, NoSQL Injection, XSS, CSRF, Parameterized Query, CSP, SameSite Cookie', N'WRITTEN', NULL, NULL),
(122, 4, N'Làm thế nào để scale một ứng dụng Node.js trong môi trường sản xuất (Production)?', N'Thiết kế ứng dụng theo hướng Không trạng thái (Stateless Service): Lưu trữ session/cache trên Redis thay vì trong RAM server. Sử dụng Reverse Proxy / Load Balancer (Nginx, AWS ALB) để phân phối lưu lượng tới nhiều instance Node.js. Đóng gói ứng dụng bằng Docker Container và điều phối tự động bằng Kubernetes (HPA) hoặc PM2 cluster mode.', N'HARD', 189, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.687', NULL, NULL, N'Scaling, Stateless, Redis, Nginx, Load Balancing, Docker, PM2, Kubernetes', N'WRITTEN', NULL, NULL),
(123, 4, N'Phương pháp phát hiện và khắc phục Memory Leak trong ứng dụng Node.js bằng Heap Snapshot và Chrome DevTools?', N'Sử dụng công cụ inspect (--inspect) kết nối Chrome DevTools để chụp Heap Snapshot tại 2 thời điểm khác nhau (trước và sau khi chạy tải mô phỏng). So sánh 2 bản snapshot (Comparison View), lọc các đối tượng có ''Retained Size'' lớn không được giải phóng. Nguyên nhân hay gặp: biến global, closure giữ tham chiếu rác, hoặc event listener không được hủy.', N'HARD', 190, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.689', NULL, NULL, N'Memory Leak, Heap Snapshot, Chrome DevTools, Retained Size, Garbage Collection, v8 inspect', N'WRITTEN', NULL, NULL),
(124, 4, N'Trình bày kiến trúc xây dựng hệ thống thời gian thực (Real-time) bằng Socket.IO và cách scale ngang khi chạy nhiều server bằng Redis Adapter?', N'Socket.IO thiết lập kết nối song công (full-duplex) dựa trên WebSocket và fallback HTTP long-polling. Khi scale ngang ra nhiều server đằng sau Load Balancer, client A kết nối ở server 1 sẽ không nhận được tin nhắn từ client B kết nối ở server 2. Giải pháp là tích hợp Socket.IO Redis Adapter sử dụng cơ chế Redis Pub/Sub để phát tán sự kiện giữa tất cả các instance server.', N'HARD', 191, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.691', NULL, NULL, N'Socket.io, WebSocket, Redis Adapter, Real-time, Pub/Sub, Horizontal Scaling', N'WRITTEN', NULL, NULL),
(125, 5, N'Mệnh đề nào trong câu truy vấn SQL được sử dụng để loại bỏ các hàng có dữ liệu trùng lặp hoàn toàn khỏi tập kết quả?', N'Từ khóa DISTINCT được đặt sau SELECT để chỉ giữ lại các dòng duy nhất.', N'EASY', 192, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.692', NULL, NULL, N'SELECT DISTINCT, SQL, trùng lặp', N'MCQ', N'[{"id": "A", "text": "SELECT UNIQUE"}, {"id": "B", "text": "SELECT DISTINCT"}, {"id": "C", "text": "SELECT DIFFERENT"}, {"id": "D", "text": "SELECT FILTER"}]', N'B');
INSERT INTO [interview_questions] ([id], [topic_id], [question_text], [sample_answer], [difficulty], [display_order], [is_active], [created_at], [updated_at], [created_by], [updated_by], [keywords], [question_type], [options_json], [correct_option_id]) VALUES
(126, 5, N'Mệnh đề nào trong SQL được dùng để lọc dữ liệu dựa trên kết quả của các hàm tổng hợp (Aggregate Functions) sau khi đã gom nhóm?', N'Mệnh đề HAVING lọc dữ liệu sau khi GROUP BY, trong khi WHERE lọc trước khi gom nhóm và không dùng được với hàm tổng hợp.', N'EASY', 193, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.694', NULL, NULL, N'HAVING, GROUP BY, Aggregate Functions, SQL', N'MCQ', N'[{"id": "A", "text": "WHERE"}, {"id": "B", "text": "HAVING"}, {"id": "C", "text": "FILTER"}, {"id": "D", "text": "ORDER BY"}]', N'B'),
(127, 5, N'Trong cơ sở dữ liệu quan hệ, mối quan hệ Nhiều - Nhiều (Many-to-Many) giữa hai bảng được hiện thực như thế nào?', N'Tạo một bảng trung gian (Junction Table / Pivot Table) chứa hai khóa ngoại tham chiếu tới khóa chính của hai bảng ban đầu.', N'EASY', 194, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.695', NULL, NULL, N'Many-to-Many, Junction Table, Foreign Key, quan hệ nhiều nhiều', N'MCQ', N'[{"id": "A", "text": "Thêm mảng ID vào một cột"}, {"id": "B", "text": "Sử dụng một bảng trung gian (Junction Table) chứa 2 khóa ngoại"}, {"id": "C", "text": "Tạo 2 khóa chính trên cùng một bảng"}, {"id": "D", "text": "Không thể biểu diễn trong RDBMS"}]', N'B'),
(128, 5, N'Khóa chính (Primary Key) trong bảng cơ sở dữ liệu bắt buộc phải thỏa mãn những điều kiện nào sau đây?', N'Primary Key phải đảm bảo tính duy nhất (Unique) cho mỗi bản ghi và tuyệt đối không được chứa giá trị NULL.', N'EASY', 195, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.697', NULL, NULL, N'Primary Key, Khóa chính, Unique, Not Null', N'MCQ', N'[{"id": "A", "text": "Chỉ cần duy nhất, cho phép chứa nhiều giá trị NULL"}, {"id": "B", "text": "Giá trị phải là duy nhất và tuyệt đối không được chứa giá trị NULL"}, {"id": "C", "text": "Bắt buộc phải là kiểu số tự tăng"}, {"id": "D", "text": "Tự động mã hóa dữ liệu"}]', N'B'),
(129, 5, N'Nêu sự khác nhau giữa INNER JOIN, LEFT JOIN, RIGHT JOIN và FULL OUTER JOIN?', N'INNER JOIN chỉ trả về các dòng thỏa mãn điều kiện khớp ở cả 2 bảng. LEFT JOIN trả về toàn bộ dòng ở bảng bên trái kèm dữ liệu khớp ở bảng phải (nếu không khớp điền NULL). RIGHT JOIN trả về toàn bộ dòng ở bảng phải. FULL OUTER JOIN trả về toàn bộ dữ liệu ở cả 2 bảng bất kể có khớp hay không.', N'EASY', 196, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.698', NULL, NULL, N'INNER JOIN, LEFT JOIN, RIGHT JOIN, FULL OUTER JOIN, SQL Joins', N'WRITTEN', NULL, NULL),
(130, 5, N'Phân biệt sự khác nhau giữa mệnh đề WHERE và HAVING trong câu lệnh SQL? Cho ví dụ minh họa?', N'WHERE lọc từng dòng đơn lẻ trước khi dữ liệu được gom nhóm, không thể sử dụng trực tiếp các hàm tổng hợp (như COUNT, SUM). HAVING lọc trên các nhóm dữ liệu sau khi đã thực hiện GROUP BY và thường đi kèm với các hàm tổng hợp (ví dụ: HAVING COUNT(*) > 5).', N'EASY', 197, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.700', NULL, NULL, N'WHERE, HAVING, GROUP BY, Aggregate, SQL Filter', N'WRITTEN', NULL, NULL),
(131, 5, N'Khái niệm Khóa ngoại (Foreign Key) và Tính toàn vẹn tham chiếu (Referential Integrity) là gì?', N'Khóa ngoại là một hoặc tập hợp các cột trong một bảng tham chiếu tới khóa chính của bảng khác. Tính toàn vẹn tham chiếu đảm bảo không thể tạo bản ghi con trỏ tới một bản ghi cha không tồn tại, đồng thời ngăn chặn việc xóa bản ghi cha khi đang có bản ghi con tham chiếu tới (hoặc thực hiện CASCADE tùy cấu hình).', N'EASY', 198, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.701', NULL, NULL, N'Foreign Key, Referential Integrity, Khóa ngoại, CASCADE, RDBMS', N'WRITTEN', NULL, NULL),
(132, 5, N'So sánh sự khác nhau giữa các câu lệnh xóa dữ liệu: DELETE, TRUNCATE và DROP trong SQL?', N'DELETE là lệnh DML xóa từng dòng dựa theo điều kiện WHERE, có ghi log chi tiết từng dòng (chậm) và có thể rollback. TRUNCATE là lệnh DDL giải phóng toàn bộ trang dữ liệu của bảng, không có WHERE, ghi log tối thiểu (cực nhanh), reset lại identity. DROP xóa hoàn toàn cả cấu trúc bảng lẫn dữ liệu và metadata khỏi cơ sở dữ liệu.', N'EASY', 199, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.703', NULL, NULL, N'DELETE, TRUNCATE, DROP, DDL, DML, Transaction Log, Rollback', N'WRITTEN', NULL, NULL),
(133, 5, N'Sự khác biệt cốt lõi nhất giữa Clustered Index và Non-Clustered Index trong cơ sở dữ liệu quan hệ là gì?', N'Clustered Index sắp xếp và lưu trữ trực tiếp các dòng dữ liệu vật lý của bảng theo thứ tự khóa chỉ mục (mỗi bảng chỉ có 1). Non-Clustered Index lưu cấu trúc B-Tree riêng biệt chứa con trỏ trỏ về dòng dữ liệu thực tế.', N'MEDIUM', 200, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.705', NULL, NULL, N'Clustered Index, Non-Clustered Index, vật lý, con trỏ dữ liệu', N'MCQ', N'[{"id": "A", "text": "Clustered Index chạy chậm hơn Non-Clustered Index"}, {"id": "B", "text": "Clustered Index sắp xếp trực tiếp dữ liệu vật lý trên ổ đĩa và mỗi bảng chỉ có duy nhất 1 Clustered Index"}, {"id": "C", "text": "Non-Clustered Index chỉ tạo được trên khóa chính"}, {"id": "D", "text": "Mỗi bảng có thể tạo vô số Clustered Index"}]', N'B'),
(134, 5, N'Một Composite Index (Chỉ mục kết hợp) được tạo trên 3 cột (A, B, C). Theo quy tắc tiền tố bên trái (Leftmost Prefix Rule), câu truy vấn nào sau đây KHÔNG THỂ tận dụng được index này?', N'Theo quy tắc tiền tố bên trái, index chỉ hoạt động nếu câu truy vấn chứa cột đầu tiên A. Nếu chỉ tìm kiếm theo B và C mà không có A, index (A, B, C) sẽ bị bỏ qua và dẫn đến Table Scan.', N'MEDIUM', 201, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.707', NULL, NULL, N'Composite Index, Leftmost Prefix Rule, Index optimization', N'MCQ', N'[{"id": "A", "text": "WHERE A = 1"}, {"id": "B", "text": "WHERE A = 1 AND B = 2"}, {"id": "C", "text": "WHERE B = 2 AND C = 3"}, {"id": "D", "text": "WHERE A = 1 AND B = 2 AND C = 3"}]', N'C'),
(135, 5, N'Mức độ cô lập giao dịch (Transaction Isolation Level) mặc định trong hầu hết các hệ quản trị CSDL quan hệ như SQL Server và PostgreSQL là gì?', N'READ COMMITTED là mức độ cô lập mặc định, đảm bảo câu truy vấn chỉ đọc các dữ liệu đã được commit, ngăn chặn hiện tượng Dirty Read.', N'MEDIUM', 202, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.708', NULL, NULL, N'READ COMMITTED, Transaction Isolation, Default level', N'MCQ', N'[{"id": "A", "text": "READ UNCOMMITTED"}, {"id": "B", "text": "READ COMMITTED"}, {"id": "C", "text": "REPEATABLE READ"}, {"id": "D", "text": "SERIALIZABLE"}]', N'B'),
(136, 5, N'Giải thích chi tiết 4 tính chất ACID của một Transaction trong cơ sở dữ liệu quan hệ?', N'Atomicity (Tính nguyên tử): Tất cả các thao tác thành công hoặc tất cả rollback. Consistency (Tính nhất quán): Dữ liệu chuyển từ trạng thái hợp lệ này sang trạng thái hợp lệ khác, tuân thủ mọi ràng buộc. Isolation (Tính cô lập): Các giao dịch đồng thời không can thiệp lẫn nhau. Durability (Tính bền vững): Dữ liệu đã commit sẽ được lưu trữ an toàn ngay cả khi hệ thống gặp sự cố mất điện.', N'MEDIUM', 203, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.710', NULL, NULL, N'ACID, Atomicity, Consistency, Isolation, Durability, Transaction', N'WRITTEN', NULL, NULL),
(137, 5, N'Trình bày 4 mức độ cô lập Transaction và các hiện tượng bất thường tương ứng (Dirty Read, Non-repeatable Read, Phantom Read)?', N'Read Uncommitted: Cho phép đọc dữ liệu chưa commit (bị Dirty Read). Read Committed: Chỉ đọc dữ liệu đã commit (chặn Dirty Read, nhưng bị Non-repeatable Read). Repeatable Read: Khóa các dòng đã đọc trong suốt transaction (chặn Non-repeatable Read, nhưng có thể bị Phantom Read khi có dòng mới chèn vào). Serializable: Mức cao nhất, thực thi tuần tự hoàn toàn, ngăn chặn toàn bộ các hiện tượng trên.', N'MEDIUM', 204, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.712', NULL, NULL, N'Isolation Levels, Dirty Read, Non-repeatable Read, Phantom Read, Serializable', N'WRITTEN', NULL, NULL),
(138, 5, N'Nguyên lý hoạt động của Index dựa trên cấu trúc B-Tree? Khi nào nên đánh Index và khi nào KHÔNG nên đánh Index?', N'B-Tree là cây tìm kiếm cân bằng tự động giúp giảm độ phức tạp tìm kiếm từ O(n) xuống O(log n). Nên đánh index trên: các cột thường xuyên xuất hiện trong WHERE, JOIN, ORDER BY, GROUP BY có độ chọn lọc cao (High Cardinality). Không nên đánh index trên: bảng quá nhỏ, cột có độ chọn lọc thấp (như giới tính nam/nữ), hoặc bảng ghi chép log có tần suất INSERT/UPDATE liên tục vì mỗi lần ghi phải cập nhật lại cây index.', N'MEDIUM', 205, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.713', NULL, NULL, N'B-Tree Index, Cardinality, High selectivity, O(log n), Table Scan', N'WRITTEN', NULL, NULL),
(139, 5, N'Cách đọc và phân tích Execution Plan trong SQL Server / PostgreSQL: Phân biệt Index Seek, Index Scan và Table Scan?', N'Index Seek: Di chuyển trực tiếp đến vị trí dòng dữ liệu cần tìm trên cây B-Tree (nhanh nhất, tối ưu nhất). Index Scan: Quét qua toàn bộ các nút lá của Index (chậm hơn seek, xảy ra khi câu query cần nhiều dòng hoặc thiếu điều kiện lọc). Table Scan: Quét toàn bộ bảng từ đầu đến cuối trang dữ liệu (chậm nhất, tiêu tốn I/O lớn khi bảng nhiều dữ liệu).', N'MEDIUM', 206, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.715', NULL, NULL, N'Execution Plan, Index Seek, Index Scan, Table Scan, Query Performance', N'WRITTEN', NULL, NULL),
(140, 5, N'Trình bày các dạng chuẩn hóa cơ sở dữ liệu (1NF, 2NF, 3NF) và khi nào cần áp dụng kỹ thuật Phi chuẩn hóa (Denormalization)?', N'1NF: Giá trị mỗi cột phải nguyên tử (atomic), không chứa mảng hay danh sách. 2NF: Đạt 1NF và mọi thuộc tính không khóa phải phụ thuộc hoàn toàn vào toàn bộ khóa chính (loại bỏ phụ thuộc một phần). 3NF: Đạt 2NF và loại bỏ phụ thuộc bắc cầu (transitive dependency). Áp dụng Phi chuẩn hóa (như lưu dư thừa tên khách hàng vào bảng đơn hàng) trong các hệ thống đọc nhiều (Data Warehouse, Dashboard) để giảm bớt số lượng JOIN phức tạp.', N'MEDIUM', 207, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.716', NULL, NULL, N'Normalization, 1NF, 2NF, 3NF, Denormalization, Data Warehouse, JOIN reduction', N'WRITTEN', NULL, NULL),
(141, 5, N'So sánh Subquery, Common Table Expression (CTE) và Bảng tạm (Temporary Table)? Khi nào nên chọn giải pháp nào?', N'Subquery: Viết trực tiếp trong câu lệnh, tiện cho các phép lọc đơn giản nhưng khó đọc nếu lồng nhiều cấp. CTE (WITH clause): Tăng tính tường minh, dễ tái sử dụng trong cùng câu query và hỗ trợ truy vấn đệ quy (Recursive CTE). Temporary Table (#TempTable): Lưu vật lý trên TempDB, có thể tạo Index riêng, cực kỳ hữu ích khi xử lý tập dữ liệu trung gian lớn qua nhiều bước tính toán phức tạp.', N'MEDIUM', 208, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.718', NULL, NULL, N'Subquery, CTE, Temporary Table, TempDB, Recursive Query, SQL Performance', N'WRITTEN', NULL, NULL),
(142, 5, N'Phân biệt Stored Procedure và User-Defined Function (UDF) trong cơ sở dữ liệu SQL?', N'Stored Procedure có thể chứa logic nghiệp vụ phức tạp, cho phép thực thi các lệnh DML (INSERT/UPDATE/DELETE), quản lý transaction độc lập, trả về nhiều tập kết quả. Function chỉ nhận tham số và bắt buộc trả về một giá trị hoặc bảng, không được phép thay đổi trạng thái dữ liệu (chỉ đọc), và có thể gọi trực tiếp trong mệnh đề SELECT/WHERE.', N'MEDIUM', 209, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.720', NULL, NULL, N'Stored Procedure, Function, UDF, DML, Transaction, Return value', N'WRITTEN', NULL, NULL),
(143, 5, N'Window Functions trong SQL (ROW_NUMBER, RANK, DENSE_RANK, LEAD, LAG) là gì và ứng dụng thực tế?', N'Window Functions tính toán trên một tập hợp các hàng liên quan (OVER partition by ... order by) mà không làm gộp các hàng lại như GROUP BY. ROW_NUMBER tạo số thứ tự liên tục (thường dùng phân trang Keyset hoặc lấy top 1 mỗi nhóm). RANK để trống thứ hạng khi trùng điểm, DENSE_RANK không để trống thứ hạng. LEAD/LAG lấy giá trị của dòng tiếp theo hoặc dòng trước đó để so sánh tăng trưởng doanh thu theo tháng.', N'MEDIUM', 210, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.722', NULL, NULL, N'Window Functions, ROW_NUMBER, RANK, DENSE_RANK, LEAD, LAG, OVER clause', N'WRITTEN', NULL, NULL),
(144, 5, N'Trình bày giải pháp phân trang hiệu năng cao với tập dữ liệu hàng triệu dòng (Offset/Limit Paging vs Keyset/Cursor-based Paging)?', N'Phân trang truyền thống ''OFFSET 1000000 LIMIT 20'' buộc DB phải quét và bỏ qua 1 triệu dòng đầu tiên trước khi lấy 20 dòng, làm chậm trầm trọng ở các trang cuối. Keyset Pagination (Cursor-based) sử dụng điều kiện WHERE id > last_seen_id ORDER BY id LIMIT 20 tận dụng trực tiếp Clustered Index Seek, thời gian thực thi ổn định O(log n) ở bất kỳ trang nào.', N'MEDIUM', 211, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.723', NULL, NULL, N'Offset Pagination, Keyset Pagination, Cursor-based, Clustered Index Seek, Big Data', N'WRITTEN', NULL, NULL),
(145, 5, N'Hiện tượng Deadlock trong cơ sở dữ liệu quan hệ xảy ra khi nào và cơ chế giải quyết tự động của RDBMS là gì?', N'Deadlock xảy ra khi giao dịch A giữ khóa tài nguyên 1 và chờ tài nguyên 2, trong khi giao dịch B giữ tài nguyên 2 và chờ tài nguyên 1. RDBMS có luồng Deadlock Monitor định kỳ phát hiện chu trình chờ và tự động chọn một transaction làm ''nạn nhân'' (Victim) để rollback và giải phóng khóa.', N'HARD', 212, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.725', NULL, NULL, N'Deadlock, Deadlock Monitor, Victim, Rollback, Circular Wait, Locking', N'MCQ', N'[{"id": "A", "text": "Cả 2 transaction tự động hoàn tất cùng lúc"}, {"id": "B", "text": "RDBMS phát hiện chu trình khóa và tự động chọn 1 transaction làm nạn nhân (Victim) để rollback"}, {"id": "C", "text": "Server bị sập và phải khởi động lại máy chủ"}, {"id": "D", "text": "Tất cả các kết nối khác vào database bị đóng"}]', N'B'),
(146, 5, N'Chiến lược phân vùng bảng (Table Partitioning) thường được chia theo tiêu chí nào phổ biến nhất trong các hệ thống lưu trữ lớn?', N'Phân vùng theo dải thời gian (Range Partitioning theo ngày/tháng/năm) là phổ biến nhất, giúp truy vấn chỉ quét các partition cần thiết (Partition Pruning) và dễ dàng lưu trữ dữ liệu cũ (Data Archiving).', N'HARD', 213, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.727', NULL, NULL, N'Table Partitioning, Range Partitioning, Partition Pruning, Big Data', N'MCQ', N'[{"id": "A", "text": "Theo thứ tự bảng chữ cái của tên người dùng"}, {"id": "B", "text": "Theo dải thời gian (Range Partitioning theo ngày/tháng/năm)"}, {"id": "C", "text": "Theo kích thước file ngẫu nhiên"}, {"id": "D", "text": "Theo địa chỉ MAC của client"}]', N'B'),
(147, 5, N'Trình bày quy trình các bước chuẩn để chẩn đoán và tối ưu hóa một câu truy vấn SQL chạy chậm (Slow Query Optimization)?', N'1. Bật Execution Plan / Query Profiler xác định thao tác tốn kém (Table Scan, Hash Match Join). 2. Kiểm tra chỉ mục (Index): Bổ sung Index Seek hoặc Covering Index (INCLUDE columns) để tránh Bookmark Lookup / Key Lookup. 3. Viết lại câu query (Sargable Query): Tránh dùng hàm trên cột ở mệnh đề WHERE (ví dụ: tránh WHERE YEAR(CreatedDate) = 2024 mà dùng WHERE CreatedDate >= ''2024-01-01''). 4. Cập nhật Statistics để DB Optimizer đưa ra kế hoạch thực thi chính xác.', N'HARD', 214, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.728', NULL, NULL, N'Slow Query Optimization, Execution Plan, Covering Index, Sargable, Statistics, Key Lookup', N'WRITTEN', NULL, NULL),
(148, 5, N'Giải thích cơ chế Khóa (Locking Mechanism: Shared Lock, Exclusive Lock) và cơ chế MVCC (Multi-Version Concurrency Control)?', N'Shared Lock (S) cho phép nhiều giao dịch cùng đọc, ngăn ghi. Exclusive Lock (X) chỉ cho 1 giao dịch giữ để ghi, ngăn mọi thao tác đọc/ghi khác. Cơ chế MVCC (sử dụng trong PostgreSQL và SQL Server Snapshot Isolation) không khóa dòng đọc; khi một giao dịch đang sửa dữ liệu, giao dịch đọc sẽ được chuyển sang đọc bản snapshot phiên bản trước đó trong TempDB/Undo Log, loại bỏ hoàn toàn việc người đọc chặn người ghi.', N'HARD', 215, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.730', NULL, NULL, N'Shared Lock, Exclusive Lock, MVCC, Snapshot Isolation, TempDB, Concurrency', N'WRITTEN', NULL, NULL),
(149, 5, N'So sánh hệ cơ sở dữ liệu quan hệ (RDBMS - PostgreSQL/MySQL) và NoSQL (MongoDB, Redis, Cassandra)? Tiêu chí lựa chọn kiến trúc phù hợp?', N'RDBMS đảm bảo chặt chẽ ACID, hỗ trợ JOIN phức tạp, phù hợp cho hệ thống tài chính, kế toán, quản lý bán hàng. MongoDB (Document) linh hoạt schema, dễ mở rộng quy mô dữ liệu JSON. Redis (In-memory Key-Value) tốc độ truy xuất microsecond, tối ưu làm Caching, Session, Queue. Cassandra tối ưu ghi cực lớn phân tán. Tiêu chuẩn chọn dựa vào Định lý CAP và yêu cầu tính toàn vẹn so với tốc độ đọc ghi.', N'HARD', 216, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.733', NULL, NULL, N'RDBMS, NoSQL, MongoDB, Redis, Cassandra, CAP Theorem, ACID', N'WRITTEN', NULL, NULL),
(150, 5, N'Trình bày các giải pháp kiến trúc cơ sở dữ liệu phục vụ hệ thống chịu tải cao và dữ liệu lớn: Read/Write Splitting, Database Sharding và High Availability (HA)?', N'Read/Write Splitting: Master nhận các thao tác ghi (INSERT/UPDATE), đồng bộ bất đồng bộ sang các Slave / Read Replicas để chia tải đọc. Database Sharding: Phân mảnh dữ liệu theo chiều ngang (Horizontal Partitioning) trên nhiều máy chủ vật lý khác nhau dựa trên Shard Key (ví dụ TenantId hoặc UserId). High Availability (HA): Thiết lập cụm Cluster (như Always On Availability Groups hoặc Patroni PostgreSQL) tự động Failover khi node chính gặp sự cố.', N'HARD', 217, 1, '2026-11-16 04:04:42.519', '2026-11-16 04:04:42.734', NULL, NULL, N'Read Write Splitting, Replication, Sharding, Shard Key, High Availability, Always On, Failover', N'WRITTEN', NULL, NULL);
