(9, 14, 18, N'aaa', N'TEXT', NULL, NULL, 1, '2026-11-10 07:39:58.507', '2026-11-10 07:40:56.335', NULL, NULL, 0.00, N'Điểm mạnh: Không có. Điểm cần bổ sung: Câu trả lời hoàn toàn vô nghĩa (aaa), không trình bày được bất kỳ kiến thức nào về cơ chế hoạt động của HashMap, hàm hashCode(), equals(), hay cách xử lý va chạm collision.', N'Chưa đạt', N'GEMINI_AI', '2026-11-10 07:40:56.335', NULL, 0, NULL, NULL, NULL),
(10, 3, 18, N'aaa', N'TEXT', NULL, NULL, 1, '2026-11-10 07:40:05.136', '2026-11-10 07:40:56.335', NULL, NULL, 0.00, N'Câu trả lời của học viên vô nghĩa, không đúng trọng tâm và không trả lời được bất kỳ ý nào trong câu hỏi phỏng vấn. Cần nắm lại kiến thức cơ bản về vấn đề N+1 Query trong JPA/Hibernate và các cách khắc phục.', N'Chưa đạt', N'GEMINI_AI', '2026-11-10 07:40:49.371', NULL, 0, NULL, NULL, NULL),
(11, 2, 18, N'aaa', N'TEXT', NULL, NULL, 1, '2026-11-10 07:40:08.931', '2026-11-10 07:40:56.335', NULL, NULL, 0.00, N'Điểm mạnh: Không có. Điểm cần bổ sung: Câu trả lời của học viên vô nghĩa (chỉ gõ ''aaa''), hoàn toàn không trả lời câu hỏi về Dependency Injection và IoC Container cũng như bỏ lỡ tất cả các từ khóa cốt lõi.', N'Chưa đạt', N'GEMINI_AI', '2026-11-10 07:40:47.261', NULL, 0, NULL, NULL, NULL),
(12, 1, 18, N'aaaa', N'TEXT', NULL, NULL, 1, '2026-11-10 07:40:23.227', '2026-11-10 07:40:56.335', NULL, NULL, 2.00, N'Nhận xét: Câu trả lời còn khá chung chung, chưa nêu bật được thuật ngữ kỹ thuật trọng tâm của câu hỏi. Điểm cần bổ sung: Nên làm rõ thêm các ý/từ khóa quan trọng như: abstract class, interface, kế thừa đơn, đa kế thừa.', N'Chưa đạt', N'AUTO_RUBRIC', '2026-11-10 07:40:45.180', NULL, 0, NULL, NULL, NULL),
(13, 1, 17, N'aa', N'TEXT', NULL, NULL, 1, '2026-11-16 01:26:46.653', '2026-11-16 01:26:46.653', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL),
(14, 1, 17, N'Abstract class co the chua ca abstract method va concrete method, Interface truoc Java 8 chi chua abstract method. Mot class chi ke thua duoc mot abstract class nhung co the implements nhieu interfaces.', N'TEXT', N'Giai thich ro rang, vi du tot.', 8.50, 1, '2026-11-16 02:59:11.594', '2026-11-16 03:00:15.095', NULL, NULL, 6.50, N'Điểm mạnh: Học viên đã trả lời đúng các ý cơ bản về bản chất phương thức, sự khác biệt giữa kế thừa đơn (single inheritance) và đa kế thừa (multiple inheritance). Điểm cần bổ sung: Chưa đề cập đến từ khóa cốt lõi về constructor, state fields (biến trạng thái) của abstract class, default method của interface và thiếu phần hướng dẫn ''khi nào nên dùng loại nào'' theo yêu cầu câu hỏi.', N'Cần cải thiện', N'GEMINI_AI', '2026-11-16 02:59:56.749', 1, 0, NULL, NULL, 8.50),
