
-- 1. Create & Select Database
IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'StarterProjectDb')
BEGIN
    CREATE DATABASE [StarterProjectDb];
END
GO

USE [StarterProjectDb];
GO

SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- 2. Drop existing tables if present in safe reverse dependency order
DROP TABLE IF EXISTS [interview_answers];
DROP TABLE IF EXISTS [interview_sessions];
DROP TABLE IF EXISTS [interview_assignments];
DROP TABLE IF EXISTS [interview_questions];
DROP TABLE IF EXISTS [interview_topics];
DROP TABLE IF EXISTS [allocations];
DROP TABLE IF EXISTS [attendances];
DROP TABLE IF EXISTS [student_score_columns];
DROP TABLE IF EXISTS [student_scores];
DROP TABLE IF EXISTS [students];
DROP TABLE IF EXISTS [mock_projects];
DROP TABLE IF EXISTS [classes];
DROP TABLE IF EXISTS [modules];
DROP TABLE IF EXISTS [module_groups];
DROP TABLE IF EXISTS [books];
DROP TABLE IF EXISTS [one_time_tokens];
DROP TABLE IF EXISTS [refresh_token];
DROP TABLE IF EXISTS [role_permissions];
DROP TABLE IF EXISTS [permissions];
DROP TABLE IF EXISTS [user_roles];
DROP TABLE IF EXISTS [roles];
DROP TABLE IF EXISTS [users];
GO

-- ==============================================================================
-- 3. CREATE TABLES & CONSTRAINTS (ALL 22 SYSTEM ENTITIES)
-- ==============================================================================

-- 2.1. Users Table
CREATE TABLE [users] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_users PRIMARY KEY CLUSTERED,
    email NVARCHAR(255) NOT NULL CONSTRAINT UQ_users_email UNIQUE,
    password_hash NVARCHAR(255) NOT NULL,
    first_name NVARCHAR(100) NOT NULL,
    last_name NVARCHAR(100) NULL,
    teacher_code NVARCHAR(50) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_users_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_users_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_users_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
CREATE UNIQUE NONCLUSTERED INDEX UQ_users_teacher_code ON [users] (teacher_code) WHERE teacher_code IS NOT NULL;
GO

-- 2.2. Roles Table
CREATE TABLE [roles] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_roles PRIMARY KEY CLUSTERED,
    name NVARCHAR(100) NOT NULL CONSTRAINT UQ_roles_name UNIQUE,
    description NVARCHAR(255) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_roles_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_roles_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_roles_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
GO

-- 2.3. User Roles Join Table (Many-to-Many: User <-> Role)
CREATE TABLE [user_roles] (
    user_id BIGINT NOT NULL,
    role_id BIGINT NOT NULL,
    CONSTRAINT PK_user_roles PRIMARY KEY CLUSTERED (user_id, role_id),
    CONSTRAINT FK_user_roles_users FOREIGN KEY (user_id) REFERENCES [users] (id) ON DELETE CASCADE,
    CONSTRAINT FK_user_roles_roles FOREIGN KEY (role_id) REFERENCES [roles] (id) ON DELETE CASCADE
);
GO

-- 2.4. Permissions Table
CREATE TABLE [permissions] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_permissions PRIMARY KEY CLUSTERED,
    name NVARCHAR(100) NOT NULL CONSTRAINT UQ_permissions_name UNIQUE,
    resource NVARCHAR(50) NOT NULL,
    action NVARCHAR(50) NOT NULL,
    description NVARCHAR(255) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_permissions_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_permissions_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_permissions_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
GO

-- 2.5. Role Permissions Join Table (Many-to-Many: Role <-> Permission)
CREATE TABLE [role_permissions] (
    role_id BIGINT NOT NULL,
    permission_id BIGINT NOT NULL,
    CONSTRAINT PK_role_permissions PRIMARY KEY CLUSTERED (role_id, permission_id),
    CONSTRAINT FK_role_permissions_roles FOREIGN KEY (role_id) REFERENCES [roles] (id) ON DELETE CASCADE,
    CONSTRAINT FK_role_permissions_permissions FOREIGN KEY (permission_id) REFERENCES [permissions] (id) ON DELETE CASCADE
);
GO

-- 2.6. Refresh Token Table (JWT Session Management)
CREATE TABLE [refresh_token] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_refresh_token PRIMARY KEY CLUSTERED,
    token_hash NVARCHAR(512) NOT NULL CONSTRAINT UQ_refresh_token_hash UNIQUE,
    user_id BIGINT NOT NULL,
    expiry_date DATETIMEOFFSET NOT NULL,
    revoked BIT NOT NULL CONSTRAINT DF_refresh_token_revoked DEFAULT (0),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_refresh_token_created_at DEFAULT (SYSUTCDATETIME()),
    CONSTRAINT FK_refresh_token_users FOREIGN KEY (user_id) REFERENCES [users] (id) ON DELETE CASCADE
);
CREATE NONCLUSTERED INDEX IX_refresh_token_user_id ON [refresh_token] (user_id);
CREATE NONCLUSTERED INDEX IX_refresh_token_expiry ON [refresh_token] (expiry_date);
GO

-- 2.7. One Time Tokens Table (Password Reset & Verification)
CREATE TABLE [one_time_tokens] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_one_time_tokens PRIMARY KEY CLUSTERED,
    token_hash NVARCHAR(256) NOT NULL CONSTRAINT UQ_one_time_tokens_hash UNIQUE,
    user_id BIGINT NOT NULL,
    type NVARCHAR(50) NOT NULL,
    expiry_date DATETIMEOFFSET NOT NULL,
    used BIT NOT NULL CONSTRAINT DF_one_time_tokens_used DEFAULT (0),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_one_time_tokens_created_at DEFAULT (SYSUTCDATETIME()),
    CONSTRAINT FK_one_time_tokens_users FOREIGN KEY (user_id) REFERENCES [users] (id) ON DELETE CASCADE
);
CREATE NONCLUSTERED INDEX IX_one_time_tokens_user_id ON [one_time_tokens] (user_id);
CREATE NONCLUSTERED INDEX IX_one_time_tokens_expiry ON [one_time_tokens] (expiry_date);
GO

-- 2.8. Books Table (Educational Library Materials)
CREATE TABLE [books] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_books PRIMARY KEY CLUSTERED,
    name NVARCHAR(100) NOT NULL CONSTRAINT UQ_books_name UNIQUE,
    description NVARCHAR(500) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_books_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_books_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_books_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
GO

-- 2.9. Module Groups Table (Dynamic Navigation Sidebar)
CREATE TABLE [module_groups] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_module_groups PRIMARY KEY CLUSTERED,
    name NVARCHAR(100) NOT NULL CONSTRAINT UQ_module_groups_name UNIQUE,
    description NVARCHAR(500) NULL,
    display_order INT NOT NULL CONSTRAINT DF_module_groups_display_order DEFAULT (0),
    is_active BIT NOT NULL CONSTRAINT DF_module_groups_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_module_groups_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_module_groups_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
GO

-- 2.10. Modules Table (System Features & Menu Sub-items)
CREATE TABLE [modules] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_modules PRIMARY KEY CLUSTERED,
    module_group_id BIGINT NOT NULL,
    title NVARCHAR(100) NOT NULL,
    url NVARCHAR(500) NULL,
    icon NVARCHAR(50) NULL,
    description NVARCHAR(500) NULL,
    display_order INT NOT NULL CONSTRAINT DF_modules_display_order DEFAULT (0),
    required_permission NVARCHAR(100) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_modules_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_modules_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_modules_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_modules_module_groups FOREIGN KEY (module_group_id) REFERENCES [module_groups] (id) ON DELETE CASCADE
);
GO

-- 2.11. Training Classes Table
CREATE TABLE [classes] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_classes PRIMARY KEY CLUSTERED,
    class_code NVARCHAR(50) NOT NULL CONSTRAINT UQ_classes_class_code UNIQUE,
    class_name NVARCHAR(150) NOT NULL,
    program_name NVARCHAR(100) NULL,
    start_date DATE NULL,
    end_date DATE NULL,
    capacity INT NOT NULL CONSTRAINT DF_classes_capacity DEFAULT (25),
    location NVARCHAR(100) NULL,
    room NVARCHAR(50) NULL,
    status NVARCHAR(30) NOT NULL CONSTRAINT DF_classes_status DEFAULT (N'PLANNING'),
    teacher_id BIGINT NULL,
    is_active BIT NOT NULL CONSTRAINT DF_classes_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_classes_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_classes_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_classes_teacher FOREIGN KEY (teacher_id) REFERENCES [users] (id) ON DELETE SET NULL
);
GO

-- 2.12. Mock Projects Table (Graduation Capstone Projects)
CREATE TABLE [mock_projects] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_mock_projects PRIMARY KEY CLUSTERED,
    project_name NVARCHAR(150) NOT NULL,
    mentor_name NVARCHAR(100) NULL,
    tech_stack NVARCHAR(255) NULL,
    repo_url NVARCHAR(500) NULL,
    status NVARCHAR(30) NOT NULL CONSTRAINT DF_mock_projects_status DEFAULT (N'PLANNING'),
    final_score DECIMAL(4,2) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_mock_projects_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_mock_projects_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_mock_projects_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
GO

-- 2.13. Students Table (Fresher Trainees)
CREATE TABLE [students] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_students PRIMARY KEY CLUSTERED,
    student_code NVARCHAR(30) NOT NULL CONSTRAINT UQ_students_student_code UNIQUE,
    full_name NVARCHAR(120) NOT NULL,
    email NVARCHAR(255) NOT NULL CONSTRAINT UQ_students_email UNIQUE,
    phone NVARCHAR(20) NULL,
    class_id BIGINT NULL,
    mock_project_id BIGINT NULL,
    user_id BIGINT NULL,
    university NVARCHAR(150) NULL,
    major NVARCHAR(100) NULL,
    gpa DECIMAL(4,2) NULL,
    status NVARCHAR(30) NOT NULL CONSTRAINT DF_students_status DEFAULT (N'ACTIVE'),
    joined_at DATETIME2(7) NOT NULL CONSTRAINT DF_students_joined_at DEFAULT (SYSUTCDATETIME()),
    is_active BIT NOT NULL CONSTRAINT DF_students_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_students_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_students_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_students_classes FOREIGN KEY (class_id) REFERENCES [classes] (id) ON DELETE SET NULL,
    CONSTRAINT FK_students_mock_projects FOREIGN KEY (mock_project_id) REFERENCES [mock_projects] (id) ON DELETE SET NULL,
    CONSTRAINT FK_students_user FOREIGN KEY (user_id) REFERENCES [users] (id) ON DELETE SET NULL
);
GO

-- 2.14. Attendances Table (Daily Trainee Presence Tracking)
CREATE TABLE [attendances] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_attendances PRIMARY KEY CLUSTERED,
    student_id BIGINT NOT NULL,
    class_id BIGINT NOT NULL,
    attendance_date DATE NOT NULL,
    slot NVARCHAR(20) NOT NULL CONSTRAINT DF_attendances_slot DEFAULT (N'MORNING'),
    status NVARCHAR(20) NOT NULL CONSTRAINT DF_attendances_status DEFAULT (N'PRESENT'),
    note NVARCHAR(255) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_attendances_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_attendances_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_attendances_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_attendances_students FOREIGN KEY (student_id) REFERENCES [students] (id) ON DELETE CASCADE,
    CONSTRAINT FK_attendances_classes FOREIGN KEY (class_id) REFERENCES [classes] (id)
);
GO

-- 2.15. Student Scores Table (Gradebook Records)
CREATE TABLE [student_scores] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_student_scores PRIMARY KEY CLUSTERED,
    student_code NVARCHAR(30) NOT NULL CONSTRAINT UQ_student_scores_student_code UNIQUE,
    student_name NVARCHAR(120) NOT NULL,
    class_name NVARCHAR(60) NOT NULL,
    overall_score DECIMAL(8,2) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_student_scores_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_student_scores_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_student_scores_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
GO

-- 2.16. Student Score Columns Table (Dynamic Score Components)
CREATE TABLE [student_score_columns] (
    student_score_id BIGINT NOT NULL,
    score_key NVARCHAR(80) NOT NULL,
    score_value DECIMAL(8,2) NULL,
    CONSTRAINT PK_student_score_columns PRIMARY KEY CLUSTERED (student_score_id, score_key),
    CONSTRAINT FK_student_score_columns_scores FOREIGN KEY (student_score_id) REFERENCES [student_scores] (id) ON DELETE CASCADE
);
GO

-- 2.17. Production Allocations Table (Job Matching & Placement)
CREATE TABLE [allocations] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_allocations PRIMARY KEY CLUSTERED,
    student_id BIGINT NOT NULL,
    target_unit NVARCHAR(100) NOT NULL,
    project_name NVARCHAR(150) NULL,
    role_title NVARCHAR(100) NOT NULL CONSTRAINT DF_allocations_role_title DEFAULT (N'Fresher Developer'),
    match_score DECIMAL(5,2) NULL,
    status NVARCHAR(30) NOT NULL CONSTRAINT DF_allocations_status DEFAULT (N'PROPOSED'),
    interview_date DATETIME2(7) NULL,
    note NVARCHAR(500) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_allocations_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_allocations_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_allocations_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_allocations_students FOREIGN KEY (student_id) REFERENCES [students] (id) ON DELETE CASCADE
);
GO

-- 2.18. Interview Topics Table (Interview Categories)
CREATE TABLE [interview_topics] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_interview_topics PRIMARY KEY CLUSTERED,
    name NVARCHAR(150) NOT NULL CONSTRAINT UQ_interview_topics_name UNIQUE,
    description NVARCHAR(500) NULL,
    display_order INT NOT NULL CONSTRAINT DF_interview_topics_display_order DEFAULT (0),
    is_active BIT NOT NULL CONSTRAINT DF_interview_topics_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_topics_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_topics_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL
);
GO

-- 2.19. Interview Questions Table (Question Bank with MCQ & Essay Support)
CREATE TABLE [interview_questions] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_interview_questions PRIMARY KEY CLUSTERED,
    topic_id BIGINT NOT NULL,
    question_text NVARCHAR(1000) NOT NULL,
    sample_answer NVARCHAR(MAX) NULL,
    keywords NVARCHAR(500) NULL,
    difficulty NVARCHAR(20) NOT NULL CONSTRAINT DF_interview_questions_difficulty DEFAULT ('MEDIUM'),
    display_order INT NOT NULL CONSTRAINT DF_interview_questions_display_order DEFAULT (0),
    question_type NVARCHAR(30) NOT NULL CONSTRAINT DF_interview_questions_question_type DEFAULT ('WRITTEN'),
    options_json NVARCHAR(MAX) NULL,
    correct_option_id NVARCHAR(20) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_interview_questions_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_questions_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_questions_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_interview_questions_topics FOREIGN KEY (topic_id) REFERENCES [interview_topics] (id) ON DELETE CASCADE
);
GO

-- 2.20. Interview Assignments Table (Exam Campaigns / Rounds)
CREATE TABLE [interview_assignments] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_interview_assignments PRIMARY KEY CLUSTERED,
    topic_id BIGINT NOT NULL,
    class_id BIGINT NULL,
    title NVARCHAR(200) NOT NULL,
    description NVARCHAR(1000) NULL,
    duration_minutes INT NOT NULL CONSTRAINT DF_interview_assignments_duration DEFAULT (45),
    total_questions INT NOT NULL CONSTRAINT DF_interview_assignments_total_questions DEFAULT (10),
    easy_count INT NOT NULL CONSTRAINT DF_interview_assignments_easy DEFAULT (4),
    medium_count INT NOT NULL CONSTRAINT DF_interview_assignments_medium DEFAULT (4),
    hard_count INT NOT NULL CONSTRAINT DF_interview_assignments_hard DEFAULT (2),
    passing_score DECIMAL(4,2) NOT NULL CONSTRAINT DF_interview_assignments_passing_score DEFAULT (7.0),
    start_time DATETIME2(7) NULL,
    end_time DATETIME2(7) NULL,
    status NVARCHAR(30) NOT NULL CONSTRAINT DF_interview_assignments_status DEFAULT ('PUBLISHED'),
    is_active BIT NOT NULL CONSTRAINT DF_interview_assignments_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_assignments_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_assignments_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_interview_assignments_topics FOREIGN KEY (topic_id) REFERENCES [interview_topics] (id) ON DELETE CASCADE,
    CONSTRAINT FK_interview_assignments_classes FOREIGN KEY (class_id) REFERENCES [classes] (id) ON DELETE SET NULL
);
GO

-- 2.21. Interview Sessions Table (Candidate Exam Attempts)
CREATE TABLE [interview_sessions] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_interview_sessions PRIMARY KEY CLUSTERED,
    assignment_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    started_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_sessions_started_at DEFAULT (SYSUTCDATETIME()),
    submitted_at DATETIME2(7) NULL,
    status NVARCHAR(30) NOT NULL CONSTRAINT DF_interview_sessions_status DEFAULT ('IN_PROGRESS'),
    total_score DECIMAL(4,2) NULL,
    ai_average_score DECIMAL(4,2) NULL,
    teacher_score DECIMAL(4,2) NULL,
    overall_verdict NVARCHAR(50) NULL,
    overall_summary NVARCHAR(MAX) NULL,
    teacher_feedback NVARCHAR(MAX) NULL,
    reviewed_by BIGINT NULL,
    reviewed_at DATETIME2(7) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_interview_sessions_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_sessions_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_sessions_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_interview_sessions_assignments FOREIGN KEY (assignment_id) REFERENCES [interview_assignments] (id) ON DELETE CASCADE,
    CONSTRAINT FK_interview_sessions_users FOREIGN KEY (user_id) REFERENCES [users] (id)
);
GO

-- 2.22. Interview Answers Table (Individual Answers & Grading)
CREATE TABLE [interview_answers] (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_interview_answers PRIMARY KEY CLUSTERED,
    question_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    session_id BIGINT NULL,
    answer_text NVARCHAR(MAX) NOT NULL,
    answer_mode NVARCHAR(20) NOT NULL CONSTRAINT DF_interview_answers_answer_mode DEFAULT ('TEXT'),
    selected_option_id NVARCHAR(20) NULL,
    is_flagged BIT NOT NULL CONSTRAINT DF_interview_answers_is_flagged DEFAULT (0),
    is_correct BIT NULL,
    teacher_note NVARCHAR(1000) NULL,
    score DECIMAL(4,2) NULL,
    teacher_score DECIMAL(4,2) NULL,
    ai_score DECIMAL(4,2) NULL,
    ai_feedback NVARCHAR(MAX) NULL,
    ai_verdict NVARCHAR(50) NULL,
    graded_by NVARCHAR(50) NULL,
    graded_at DATETIME2(7) NULL,
    is_active BIT NOT NULL CONSTRAINT DF_interview_answers_is_active DEFAULT (1),
    created_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_answers_created_at DEFAULT (SYSUTCDATETIME()),
    updated_at DATETIME2(7) NOT NULL CONSTRAINT DF_interview_answers_updated_at DEFAULT (SYSUTCDATETIME()),
    created_by BIGINT NULL,
    updated_by BIGINT NULL,
    CONSTRAINT FK_interview_answers_questions FOREIGN KEY (question_id) REFERENCES [interview_questions] (id) ON DELETE CASCADE,
    CONSTRAINT FK_interview_answers_sessions FOREIGN KEY (session_id) REFERENCES [interview_sessions] (id),
    CONSTRAINT FK_interview_answers_users FOREIGN KEY (user_id) REFERENCES [users] (id)
);
GO

